            base_price = domutils.textContent(CSSselect.selectOne("#price_feature_div span.centralizedApexPricePriceToPayMargin", dom) ?? '')?.trim()?.replace('$', '')?.replace(',', '');
            // console.log('base_price signed in', base_price);
