import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class AmazonShoppingCartParser {
  watchURLChanges() {
    return false;
  }
  
  normalizeUrl(url) {
    let asin = this.merchantIdFromURL(url);
    return 'https://www.amazon.com/dp/' + asin + '?th=1&psc=1';
  }

  isProductPage(url) {
    // https://www.amazon.com/ALASKA-BEAR-Contoured-Blindfold-Meditation/dp/B07R558RLV
    let result =
      /\/dp\/(\w+)/.test(url)
      || /\/gp\/product\/(\w+)/.test(url)
    ;
    // console.log('entered amazon isProductPage', url, result);
    return result;
  }
  

  getMerchant() {
    return 'amazonWishlist';
  }

  merchantIdFromURL(url, html='') {
    let asin = '';
    let asin_matches = url.match(/\/dp\/(\w+)/);
    if(asin_matches !== null && asin_matches.length > 1) {
      asin = asin_matches[1];
    }
  
    // get everything between /gp/ and ? or /
    asin_matches = url.match(/\/gp\/product\/(\w+)/);
    if(asin_matches !== null && asin_matches.length > 1) {
      asin = asin_matches[1];
    }
  
    return asin;
  }

  getAddAlertInjection() {
    return {
      selector: "#apex_desktop, div[data-a-expander-name='book_description_expander']",
      insertAdjacentPosition: "beforebegin",
    };
  }

  parse(html, url) {
    try {
      let startTime = performance.now()

      const dom = htmlparser2.parseDocument(html);
      console.log('brian shopping cart or saved for later parser');

      let shoppingcart_urls = [];
      let shoppingcart_url = '';
      let shoppingcart_urls_nl = CSSselect.selectAll("form[id='activeCartViewForm'] a[class*='sc-product-title']", dom) ?? [];
      shoppingcart_urls_nl.forEach(  (url_row) => {
        shoppingcart_url = 'https://www.amazon.com'+domutils.getAttributeValue(url_row, 'href').trim();
        shoppingcart_urls.push( shoppingcart_url );
      });

      console.log('shoppingcart_urls', shoppingcart_urls);

      let savedforlater_urls = [];
      let savedforlater_url = '';
      let savedforlater_urls_nl = CSSselect.selectAll("form[id='savedCartViewForm'] a[class*='sc-product-title']", dom) ?? [];
      savedforlater_urls_nl.forEach(  (url_row) => {
        savedforlater_url = 'https://www.amazon.com'+domutils.getAttributeValue(url_row, 'href').trim();
        savedforlater_urls.push( savedforlater_url );
      });

      console.log('savedforlater_urls', savedforlater_urls);

      
      let product = {
        'shoppingcart_urls': shoppingcart_urls,
        'savedforlater_urls': savedforlater_urls,
      };


      // console.log('product', product);
      let endTime = performance.now()
      // console.log(`parseAmazonProduct: ${endTime - startTime} milliseconds`);
      return product;
    }
    catch (err) {
      console.log('AmazonShoppingCartParser.js error', err);
      return null;
    }
  }
}


export {AmazonShoppingCartParser};