import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class OfficedepotParser {
  watchURLChanges() {
    return false;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, []);
  }
  
  isProductPage(url) {
    // https://www.officedepot.com/a/products/7217871/Bounty-Select-A-Size-2-Ply/
    let result = /\/a\/products\//.test(url);
    return result;
  }

  getMerchant() {
    return 'officedepot';
  }

  merchantIdFromURL(url, html='') {
    let result = url.match(/\/products\/([\d]+)\//);
    return result?.[1];
  }

  getAddAlertInjection() {
    return {
      selector: "div[class='od-graphql-price']",
      insertAdjacentPosition: "afterbegin",
    };
  }

  

  parse(html, url) {
    try {
      const dom = htmlparser2.parseDocument(html);
      // get title, link, merchant_product_id, image_link, price (is shipping diff than pickup?), coupon, details, specifications
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();

      // link
      let link = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:url']", dom), 'content')?.trim() ?? '';

      // merchant_product_id - just make link for now
      let merchant_product_id = '';
      let merchant_product_id_match = link.match(/\/products\/([\d]+)\//);
      merchant_product_id = merchant_product_id_match[1];

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("div[class='image-gallery-image'] img", dom), 'src')?.trim() ?? '';

      // price
      let price = domutils.textContent(CSSselect.selectOne("span[class='od-graphql-price-big-price']", dom) ?? '')?.trim();
      price = price.replace("$", "");
      price = price.replace(",", "");
  
      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    }
    catch (err) {
      console.log('OfficedepotParser.js error', err);
      return null;
    }
  }

}

export {OfficedepotParser};