import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class BananaRepublicCaParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['pid']);
  }
  
  isProductPage(url) {
    // https://bananarepublic.gap.com/browse/product.do?pid=800139122&rrec=true&mlink=5001,1,home_brhome4_rr_0&clink=1#pdp-page-content
    let result = /\/product\.do/.test(url);
    return result;
  }

  getMerchant() {
    return 'bananarepublicCa';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
      type: 'function',
      fun: function (doc, containing_span) {
        
        doc.querySelectorAll("h1").forEach((h1, index) => {
          h1.insertAdjacentElement('beforebegin', containing_span);
        });         

      },
      selector: "h1",

    };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();
      title = 'Banana Republic ' + title;

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("div[class*='pdp-photo-single-column-image']", dom), 'data-imageurl')?.trim() ?? '';
      image_link = 'https://www.gap.com'+image_link

      // price
      let price = domutils.textContent(CSSselect.selectOne("span[class*='core-web-purchase-price']", dom) ?? '')?.trim();
         
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
      price = price.replace("CA", "").trim();
    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('BananaRepublicCaParser.js error', err);
      return null;
    }
  }

}

export {BananaRepublicCaParser};