import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class HermanMillerParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['lang', 'sku']);
  }
  
  isProductPage(url) {
    // https://store.hermanmiller.com/office-chairs-aeron/aeron-chair/100100032.html?lang=en_US&sku=100100032
    let result = /\.html/.test(url);
    return result;
  }

  getMerchant() {
    return 'hermanmiller';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }



  getAddAlertInjection() {
    return {
        selector: "div[class*='pdp-prices'] .price",
        type: 'function',
        fun: function (doc, containing_span) {
          
          doc.querySelectorAll("div[class*='pdp-prices'] .price").forEach((h1, index) => {
            h1.insertAdjacentElement('beforebegin', containing_span);
          });         
        },

      };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();
      title = "Herman Miller " + title;

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("meta[itemprop='image']", dom), 'content')?.trim() ?? '';

      // price
      let price = domutils.textContent(CSSselect.selectOne("span[class='sales']", dom) ?? '')?.trim();
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("C ", "");
      price = price.replace("USD", "").trim();
    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('HermanMillerParser.js error', err);
      return null;
    }
  }

}

export {HermanMillerParser};