import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class AmazonCaParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    let asin = this.merchantIdFromURL(url);
    return 'https://www.amazon.ca/dp/' + asin + '?th=1&psc=1';
  }

  isProductPage(url) {
    // https://www.amazon.ca/Botanic-Hearth-Strengthening-Nourishing-Volumizing/dp/B0C6XJMSGP/
    let result =
      /\/dp\/(\w+)/.test(url)
      || /\/gp\/product\/(\w+)/.test(url)
    ;
    // console.log('entered amazon isProductPage', url, result);
    return result;
  }

  getMerchant() {
    return 'amazonCa';
  }

  merchantIdFromURL(url, html='') {
    let asin = '';
    let asin_matches = url.match(/\/dp\/(\w+)/);
    if(asin_matches !== null && asin_matches.length > 1) {
      asin = asin_matches[1];
    }
  
    // get everything between /gp/ and ? or /
    asin_matches = url.match(/\/gp\/product\/(\w+)/);
    if(asin_matches !== null && asin_matches.length > 1) {
      asin = asin_matches[1];
    }
  
    return asin;
  }

  getAddAlertInjection() {
    return {
      selector: "#apex_desktop, div[data-a-expander-name='book_description_expander']",
      insertAdjacentPosition: "beforebegin",
    };
  }

  parse(html, url) {
    try {
      let startTime = performance.now()

      const dom = htmlparser2.parseDocument(html);
      
      let url = domutils.getAttributeValue(CSSselect.selectOne("link[rel='canonical']", dom), 'href')?.trim() ?? ''
      let merchant_product_id = this.merchantIdFromURL(url);

      // Title
      let title = domutils.textContent(CSSselect.selectOne("span[id='productTitle']", dom) ?? '')?.trim();
      // console.log('title', title);
      
      // Grab the 'Visit the X Store' 
      let store_name = domutils.textContent(CSSselect.selectOne("a[id='bylineInfo']", dom) ?? '')?.trim() ;
      // console.log('store_name', store_name);

      // Product Overview Features
      let product_features = [];
      let product_features_rows_nl = CSSselect.selectAll("div[id='productOverview_feature_div'] table tr", dom) ?? [];
      product_features_rows_nl.forEach( (product_features_row) => {
        let tds = CSSselect.selectAll("td", product_features_row);
        // First TD is the attribute name
        // Second TD is the attribute value
        product_features[ domutils.textContent(tds?.[0] ?? '')?.trim()?.toLowerCase()  ] = domutils.textContent(tds?.[1] ?? '')?.trim()?.toLowerCase();
      });
      // console.log('product_features', product_features);

      // About this item (bullets)
      let bullets = [];
      let bullets_nl = CSSselect.selectAll("div[id='feature-bullets'] ul li", dom) ?? [];
      bullets_nl.forEach(  (bullets_row) => {
        bullets.push( domutils.textContent(bullets_row ?? '').trim() );
      });
      // console.log('bullets', bullets);
    
      // Product Information - Technical Details
      let pi_tech_specs = [];
      let pi_tech_specs_nl = CSSselect.selectAll("table[id='productDetails_techSpec_section_1'] tr", dom) ?? [];
      // console.log('pi_tech_specs_nl', pi_tech_specs_nl);
      pi_tech_specs_nl.forEach( (pi_tech_specs_row) => {
        // First TD is the attribute name
        // Second TD is the attribute value
        // let tds = select('./x:td|./x:th', pi_tech_specs_row);
        let tds = CSSselect.selectAll("td, th", pi_tech_specs_row);
        let key = domutils.textContent(tds?.[0] ?? '')?.trim()?.toLowerCase()
        let value = domutils.textContent(tds?.[1] ?? '')?.trim()?.toLowerCase()

        pi_tech_specs[key] = value;
        
        // $key = str_replace(['&lrm;', '&rlm;'], '', $key);
        // $key = preg_replace('/[\x00-\x1F\x80-\xFF]/', '', $key);
        // $key = trim($key, " \n\r\t\v\x00:");
        // $key = strtolower($key);

        // $value = str_replace(['&lrm;', '&rlm;'], '', $value);
        // $value = preg_replace('/[\x00-\x1F\x80-\xFF]/', '', $value);
        // $value = trim($value, " \n\r\t\v\x00:");
      });
      // console.log('pi_tech_specs', pi_tech_specs);

      // Product Information - Additional Information
      let pi_additional_information = [];
      let pi_additional_information_nl = CSSselect.selectAll("table[id='productDetails_detailBullets_sections1'] tr", dom) ?? [];
      pi_additional_information_nl.forEach( (pi_additional_information_row) => {
        let tds = CSSselect.selectAll("td, th", pi_additional_information_row); 
          // First TD is the attribute name
          // Second TD is the attribute value
          pi_additional_information[domutils.textContent(tds?.[0] ?? '')?.trim()?.toLowerCase()] = domutils.textContent(tds?.[1] ?? '')?.trim()?.toLowerCase();
      });
      // console.log('pi_additional_information', pi_additional_information);


      // Variants - TODO Rob if JSON5 faster way
      let variants = {};
      try {
        let regex = /twister-js-init-dpx-data', function\(\) {\s+var dataToReturn =\s({[^;]*});/gms;
        let matches = regex.exec(html);
        if (matches!=null && matches.length>=2) {
          // let data = JSON5.parse(matches?.[1]);
          let data = JSON.parse(matches?.[1].replace(/,(\s*[\]\}])/g, "$1"));

          let invertVariationDisplayLabels = ParserUtilities.objectFlip(data?.['variationDisplayLabels'] ?? {});
          let invertDisplayLables = [];
          for (const [key, value] of Object.entries(data?.['variationValues'] ?? {})) {
            invertDisplayLables[data['variationDisplayLabels'][key]] = value;
          }
              
          
          let selected_variations = [];
          for (const [key, value] of Object.entries(data?.['selected_variations'] ?? {})) {
            selected_variations[data['variationDisplayLabels'][key]] = value;
          }

          variants = {
            'dimensions': data?.['dimensions'] ?? {},
            'dimensionsDisplay': data?.['dimensionsDisplay'] ?? {},
            'variationDisplayLabels': invertDisplayLables,
            'variationValues': invertVariationDisplayLabels,
            'selected_variations': selected_variations,
            'dimensionValuesDisplayData': data?.['dimensionValuesDisplayData'] ?? {},
            'currentAsin': data?.['currentAsin'] ?? {},
            'parentAsin': data?.['parentAsin'] ?? {},
          };
          // console.log('variants', variants);
        }
      }
      catch (err) {
        variants = {};
      }
      
      // Coupon
      let coupon_raw_text = domutils.textContent(CSSselect.selectOne("div[id='promoPriceBlockMessage_feature_div'] label[id*='couponText'], div[id='promoPriceBlockMessage_feature_div'] span[class='a-size-base a-color-success']", dom) ?? '')?.trim();
      // console.log('coupon_raw_text', coupon_raw_text);
      let coupon_regexes = [
        /Apply \$?([\d,\.]+)%? coupon/gms,
        /Save an extra \$?([\d,\.]+)%? on your first Subscribe and Save order/gms,
        /Save \$?([\d,\.]+)%?:\s+Coupon available when you select\s+Subscribe & Save/gms,
        /Save \$?([\d,\.]+)%?/gms,
        /\$?([\d,\.]+)%? off coupon applied/gms,
      ];
      let coupon_type = null;
      let coupon_amount = 0;
      let coupon_parsed_raw_text = null;

      for (let n=0; n<coupon_regexes.length; n++) {
        let coupon_regex = coupon_regexes[n];
        let coupon_parsed = coupon_regex.exec(coupon_raw_text);
        // coupon_parsed[0] is the full match (Apply 15% coupon)
        // coupon_parsed[1] is just the number (15)
        
        // Determine coupon_type
        // If this regex didn't work let's try some more
        if (coupon_parsed!=null && coupon_parsed.length==2) {
          if (coupon_parsed[0].includes("$")) {
            coupon_type = '$';
          }
          else if (coupon_parsed[0].includes("%")) {
            coupon_type = '%';
          }
          coupon_amount = coupon_parsed?.[1] ?? 0;
          coupon_parsed_raw_text = coupon_parsed?.[0] ?? null;
          
          // If we've found one coupon let's break for now
          break;
        }
      }
      // console.log({'coupon_type': coupon_type, 'coupon_amount': coupon_amount});
      
      
      
      

      // Price
      let price_json = domutils.textContent(CSSselect.selectOne("div[class*='twister-plus-buying-options-price-data']", dom) ?? '')?.trim();
      if (price_json == '') {
        price_json = 'null';
      }
      let prices = JSON.parse(price_json);
      // Other price options:
          //div[@id='dynamic-aod-ingress-box']
          //div[@id='corePriceDisplay_desktop_feature_div']
      // console.log(prices);
      
      
      // in case of "Try free for 7 days": https://www.amazon.com/Timberland-Classic-Premium-Wheat-Nubuck/dp/B000G21FRE/
      let price_try_free_7_days = '';
      if (prices==null && html!=null && html.includes('Try free for 7 days')) {
        // console.log('found try free for 7 days'); 
        price_try_free_7_days = domutils.textContent(CSSselect.selectOne("span[class='a-price a-text-price a-text-normal']", dom) ?? '');
        price_try_free_7_days = parseFloat(price_try_free_7_days.replace('$', '')?.replace(',', '').trim());
        // console.log('price_try_free_7_days', price_try_free_7_days)
      }

      // in case of whole foods local delivery (and few other cases where prices will be null) https://www.amazon.com/dp/B00JJZN1HG/
      let lowest_price_local_delivery = 0; 
      if (prices==null && price_try_free_7_days == '') {
        // get regular price
        let base_price = domutils.textContent(CSSselect.selectOne("div[id='apex_offerDisplay_desktop'] span[class='a-price a-text-normal aok-align-center reinventPriceAccordionT2'] > span[class='a-offscreen']", dom) ?? '')?.trim()?.replace('$', '')?.replace(',', '');
        // console.log('base_price', base_price);
        
        // get sns base price
        let sns_base_price = domutils.textContent(CSSselect.selectOne("span[id='sns-base-price'] span[class='a-price a-text-normal aok-align-center reinventPriceAccordionT2'] > span[class='a-offscreen']", dom) ?? '')?.trim()?.replace('$', '')?.replace(',', '');
        // console.log('sns_base_price', sns_base_price);

        // get sns tiered price
        let sns_tiered_price = domutils.textContent(CSSselect.selectOne("span[id='sns-tiered-price'] span[class='a-price a-text-normal aok-align-center reinventPriceAccordionT2'] > span[class='a-offscreen']", dom) ?? '')?.trim()?.replace('$', '')?.replace(',', '');
        // console.log('sns_tiered_price', sns_tiered_price);

        base_price = parseFloat(base_price);
        sns_base_price = parseFloat(sns_base_price);
        sns_tiered_price = parseFloat(sns_tiered_price);

        // console.log('base_price post float', base_price);
        // console.log('sns_base_price post float', sns_base_price);
        // console.log('sns_tiered_price post float', sns_tiered_price);

        // get lowest price of three
        // if only base_price is set
        if(!isNaN(base_price) && isNaN(sns_base_price) && isNaN(sns_tiered_price)) {
          lowest_price_local_delivery = base_price;
        } 
        // if all three are set
        else if(!isNaN(base_price) && !isNaN(sns_base_price) && !isNaN(sns_tiered_price)) {
          lowest_price_local_delivery  = Math.min(base_price, sns_base_price, sns_tiered_price);
        }

        // console.log('lowest_price_local_delivery', lowest_price_local_delivery);
      }

      // last price check if everything else fails, ex: https://www.amazon.com/dp/B0CNH3CNVP/
      let last_price_if_all_else_fails = 0;
      if (prices==null && price_try_free_7_days == '' && lowest_price_local_delivery == 0) {
        let last_price = domutils.textContent(CSSselect.selectOne("div[class='a-box-inner'] div[id='apex_offerDisplay_desktop'] span[class='a-price aok-align-center'] > span[class='a-offscreen']", dom) ?? '')?.trim()?.replace('$', '')?.replace(',', '');
        
        last_price = parseFloat(last_price);
        // console.log('last_price', last_price);
        if(!isNaN(last_price)) {
          last_price_if_all_else_fails = last_price;
        }
        // console.log('last_price_if_all_else_fails', last_price_if_all_else_fails);
      }

      let price = null;
      // bundle product: https://www.amazon.com/dp/B0BH7QTZGN
      let price1_check = 
        prices?.['desktop_buybox_group_1']?.[1]?.['buyingOptionType'] == 'NEW'
        || prices?.['desktop_buybox_group_1']?.[1]?.['buyingOptionType'] == 'LIGHTNING_DEAL'
        || prices?.['desktop_buybox_group_1']?.[1]?.['buyingOptionType'] == 'SNS'
        || prices?.['desktop_buybox_group_1']?.[1]?.['buyingOptionType'] == 'BUNDLE';
      let price2_check =
        prices?.['desktop_buybox_group_1']?.[0]?.['buyingOptionType'] == 'NEW'
        || prices?.['desktop_buybox_group_1']?.[0]?.['buyingOptionType'] == 'LIGHTNING_DEAL'
        || prices?.['desktop_buybox_group_1']?.[0]?.['buyingOptionType'] == 'SNS'
        || prices?.['desktop_buybox_group_1']?.[0]?.['buyingOptionType'] == 'BUNDLE';

      
      let price3_check = 
          price_try_free_7_days != '' 
          && price_try_free_7_days > 0;

      

      if(price1_check) {
          price = prices?.['desktop_buybox_group_1']?.[1]?.['priceAmount'] ?? '';
      }
      if(price == null && price2_check) {
          price = prices?.['desktop_buybox_group_1']?.[0]?.['priceAmount'] ?? '';
      }
      // usually s&s is in the [1] element, but found a case where it's in the [0], so choose lower of the two
      if(price1_check && price2_check) {
          price = Math.min(prices?.['desktop_buybox_group_1']?.[1]?.['priceAmount'], prices?.['desktop_buybox_group_1']?.[0]?.['priceAmount']);
      }
      if(price == null && price3_check) {
          price = price_try_free_7_days;
      }
      if(price == null && lowest_price_local_delivery > 0) {
        price = lowest_price_local_delivery;
      }
      if(price == null && last_price_if_all_else_fails > 0) {
        price = last_price_if_all_else_fails;
      }

      // Apply coupon to price
      // console.log({'coupon_type': coupon_type, 'coupon_amount': coupon_amount});
      if (coupon_type=='%') {
        price = price * (100 - coupon_amount) / 100
      }
      else if (coupon_type=='$') {
        price = price - coupon_amount;
      }
      
      // make price='' if it's null to prevent later NaN issue
      if(price == null) {
        price = '';
      }


      // console.log('price_information', {
      //   'prices':prices,
      //   'price_try_free_7_days':price_try_free_7_days,
      //   'price1_check': price1_check,
      //   'price2_check': price2_check,
      //   'price3_check': price3_check,
      //   'price': price,
      // });


      // Images
      let images = [];
      try {
        let image_regex = /ImageBlockATF", function\(A\){\s+var data =\s{[^;]*colorImages':\s({[^;\r\n]*}),\n/gms;
        let image_matches = image_regex.exec(html);
        images = JSON.parse(image_matches?.[1].replace("'initial'", '"initial"'));
      }
      catch (err) {
        images = [];
      }
      // console.log('images', images);
      

      // Get Description
      let description = domutils.textContent(CSSselect.selectOne("div[id='productDescription']", dom) ?? '')?.trim();
      // console.log('description', description);

      // Get product details
      let detail_bullets = {};
      let detail_bullets_nl = CSSselect.selectAll("div[id='detailBullets_feature_div'] ul li", dom) ?? [];
      detail_bullets_nl.forEach( (detail_bullet_node) => {
        let spans = CSSselect.selectAll("span span", detail_bullet_node); 
        let key = domutils.textContent(spans?.[0] ?? '')?.trim()
        key = key.replace(/[\u200E\u200F]/gi, '').replace(':', '').trim().toLowerCase(); // utf8 for &lrm; or &rlm
        /*
        console.log('key', key);
        const encoder = new TextEncoder();
        console.log('encoder-key', encoder.encode(key));
        */

        detail_bullets[key] = domutils.textContent(spans?.[1] ?? '')?.trim()
      });
      // console.log('detail_bullets', detail_bullets);

      variants = ParserUtilities.replaceAllObjKeys(variants);
      let product = {
        'title': title,
        // Why isn't link here?
        'merchant_product_id': merchant_product_id,
        'store_name': store_name,
        'product_features': product_features,
        'bullets': bullets,
        'pi_tech_specs': pi_tech_specs,
        'pi_additional_information': pi_additional_information,
        'variants': variants,
        'prices': prices,
        'price': price,
        // 'coupon': {
          'coupon_raw_text': coupon_parsed_raw_text,
          'coupon_type': coupon_type,
          'coupon_amount': coupon_amount,
        // },
        // 'images': images,
        'image_link': images?.['initial']?.[0]?.['large'] ?? '',
        'detail_bullets': detail_bullets,
      };


      // Process some of the information
      let processed_search_title = title.toLowerCase();
      let processed_color = variants?.['selected_variations']?.['color'] ?? '';
      let processed_size = variants?.['selected_variations']?.['size'] ?? '';
      if(processed_color == '' && product?.['product_features']?.['color']!=undefined && product['product_features']['color'].length > 0 && processed_search_title.includes( product['product_features']['color'].toLowerCase() ) ) {
          processed_color = product?.['product_features']?.['color'];
      }
      if(processed_color == '' && product?.['pi_additional_information']?.['color']!=undefined && product['pi_additional_information']['color'].length > 0 && processed_search_title.includes( product['pi_additional_information']['color'].toLowerCase() ) ) {
          processed_color = product['pi_additional_information']['color'];
      }
      if(processed_color.length > 0 && !processed_search_title.includes(processed_color.toLowerCase())) {
          processed_search_title = processed_search_title + ' ' + processed_color;
      }

      if(processed_size.length > 0 && !processed_search_title.includes(processed_size.toLowerCase())) {
          processed_search_title = processed_search_title + ' ' + processed_size;
      }
      

      product['processed'] = {        
          'search_title': processed_search_title,
          'size': processed_size,
          'color': processed_color,
      };

      // console.log('product', product);
      let endTime = performance.now()
      // console.log(`parseAmazonProduct: ${endTime - startTime} milliseconds`);
      return product;
    }
    catch (err) {
      console.log('amazon_parse.js error', err);
      return null;
    }
  }
}


export {AmazonCaParser};