import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class SheinParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, []);
  }
  
  isProductPage(url) {
    // https://us.shein.com/INAWLY-2pcs-Women-s-Solid-Color-Crew-Neck-Long-Sleeve-T-Shirt-And-Waist-Tie-Pants-Casual-Suit-Spring-Autumn-p-42550056.html
    let result = /\-p\-[\d]+\.html/.test(url);
    return result;
  }

  getMerchant() {
    return 'shein';
  }

  merchantIdFromURL(url, html='') {
    let merchant_product_id_match = url.match(/\-p\-([\d]+)\.html/);
    return merchant_product_id_match?.[1];
  }

  getAddAlertInjection() {
    return {
        selector: "div[class*='product-intro_']",
        insertAdjacentPosition: "afterend",
      };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = '';
      let merchant_product_id_match = url.match(/\-p\-([\d]+)\.html/);
      merchant_product_id = merchant_product_id_match?.[1];

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("div[class='crop-image-container']", dom), 'data-before-crop-src')?.trim() ?? '';

      // price
      let price = domutils.getAttributeValue(CSSselect.selectOne("meta[property='product:price:amount']", dom), 'content')?.trim() ?? '';
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('SheinParser.js error', err);
      return null;
    }
  }

}

export {SheinParser};