import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class AthletaParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['pid']);
  }
  
  isProductPage(url) {
    // https://athleta.gap.com/browse/product.do?pid=798638242&cid=1059481&pcid=1059481&vid=1&nav=meganav%3ABottoms%3ACATEGORIES%3ALeggings&cpos=2&cexp=3064&kcid=CategoryIDs%3D1059481&cvar=27654&ctype=Listing&cpid=res25011511186907116876406&ccam=42020#pdp-page-content
    let result = /\/product\.do/.test(url);
    return result;
  }

  getMerchant() {
    return 'athleta';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
      type: 'function',
      fun: function (doc, containing_span) {
        
        doc.querySelectorAll("h1").forEach((h1, index) => {
          h1.insertAdjacentElement('beforebegin', containing_span);
        });         

      },
      selector: "h1",
    };
  }



  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();
      title = 'Athleta ' + title;

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("div[class='pdp-photo-brick-image']", dom), 'data-imageurl')?.trim() ?? '';
      image_link = 'https://www.gap.com'+image_link
      
      // price
      let price = domutils.textContent(CSSselect.selectOne("span[class*='current-black-promo-price']", dom) ?? '')?.trim();
      if(price == '') {
        price = domutils.textContent(CSSselect.selectOne("span[class*='current-regular-price']", dom) ?? '')?.trim();
      }
      if(price == '') {
        price = domutils.textContent(CSSselect.selectOne("span[class*='current-sale-price']", dom) ?? '')?.trim();
      }
         
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('AthletaParser.js error', err);
      return null;
    }
  }

}

export {AthletaParser};