import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class TractorSupplyParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['variant', 'size']);
  }
  
  isProductPage(url) {
    // https://www.tractorsupply.com/tsc/product/producers-pride-farmhouse-tractor-chicken-coop-4-6-bird-capacity
    let result = /\/product\//.test(url);
    return result;
  }

  getMerchant() {
    return 'tractorsupply';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
      type: 'function',
      fun: function (doc, containing_span) {
        let price_match = doc.body.outerHTML.match(/"minOfferPrice"\:\"([\d\.\,]+)\"\,/);
        let price = price_match?.[1] ?? '';
        if(price == '') {
          let price_match2 = doc.body.outerHTML.match(/"maxOfferPrice"\:\"([\d\.\,]+)\"\,/);
          price = price_match2?.[1] ?? '';
        }

        // if price still empty return null, so won't inject
        if(price == '') {
          let titleBlock = doc.querySelector("title");
          titleBlock.insertAdjacentElement('afterend', containing_span);
          return null;
        }

          doc.querySelectorAll("h1").forEach((h1, index) => {
            h1.insertAdjacentElement('afterend', containing_span);
          });  
       

        return;
      },
      selector: "h1",
    };
  }



  // getAddAlertInjection() {
  //   return {
  //       selector: "h1",
  //       type: 'function',
  //       fun: function (doc, containing_span) {
          
  //         doc.querySelectorAll("h1").forEach((h1, index) => {
  //           h1.insertAdjacentElement('afterend', containing_span);
  //         });         
  //       },

  //     };
  // }
  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:image']", dom), 'content')?.trim() ?? '';
      image_link = image_link.replace('wid=40', 'wid=200');
      image_link = image_link.replace('hei=40', 'hei=200');

      // price
      let price_match = html.match(/minOfferPrice\: \'([\d\.\,]+)\'\,/);
      let price = price_match?.[1] ?? '';
      if(price == '') {
        let price_match2 = html.match(/maxOfferPrice\: \'([\d\.\,]+)\'\,/);
        price = price_match2?.[1] ?? '';
      }
      price = price.replace(",", "");

      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('TractorSupplyParser.js error', err);
      return null;
    }
  }

}

export {TractorSupplyParser};