import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class StaplesParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, []);
  }
  
  isProductPage(url) {
    // https://www.staples.com/paper-mate-clearpoint-mechanical-pencil-0-7mm-2-medium-lead-2-pack-56047/product_615721
    let result = /\/product_/.test(url);
    return result;
  }

  getMerchant() {
    return 'staples';
  }

  merchantIdFromURL(url, html='') {
    return url.split("/product_").pop();
  }

  getAddAlertInjection() {
    return {
      selector: "div[class='price-info__price_section']",
      insertAdjacentPosition: "beforebegin",
    };
  }

  

  parse(html, url) {
    try {
      const dom = htmlparser2.parseDocument(html);
      // get title, link, merchant_product_id, image_link, price (is shipping diff than pickup?), coupon, details, specifications
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();

      // link
      let link = 'https://www.staples.com'+domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:url']", dom), 'content')?.trim() ?? '';

      // merchant_product_id - parse out of link /product_24548561
      let merchant_product_id = link.split("/product_").pop();

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("div[class='sticky-CTA-UX2__product_image'] img", dom), 'alt')?.trim() ?? '';

      // price
      let price = domutils.textContent(CSSselect.selectOne("div[class*='price-info__final_price_sku']", dom) ?? 'null')?.trim();
      price = price.replace("Final price", "");
      price = price.replace("is", "").trim();
      
      price = price.replace("$", "");
      price = price.replace(",", "");
  
      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    }
    catch (err) {
      console.log('StaplesParser.js error', err);
      return null;
    }
  }

}

export {StaplesParser};