import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class TheNorthFaceParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['color', 'size']);
  }
  
  isProductPage(url) {
    // https://www.thenorthface.com/en-us/bags-and-gear/backpacks-c224451/womens-borealis-backpack-pNF0A52SI?color=55U&size=OS
    let result = /\/p\//.test(url);
    return result;
  }

  getMerchant() {
    return 'thenorthface';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
      type: 'function',
      fun: function (doc, containing_span) {
        
        doc.querySelectorAll("h1").forEach((h1, index) => {
          h1.insertAdjacentElement('afterend', containing_span);
        });         

      },
      selector: "h1",

    };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();
      title = 'The North Face ' + title;
      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("meta[name='og:image']", dom), 'content')?.trim() ?? '';


      // price
      let price = domutils.textContent(CSSselect.selectOne("div[data-test-id='product-pricing']:not([show-dynamic-pricing-on-plp]) ins[class*='c-red-30']", dom) ?? '')?.trim();
      if(price == '') {
        price = domutils.textContent(CSSselect.selectOne("div[data-test-id='product-pricing']", dom) ?? '')?.trim();
        if(price == '') {
          price = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:price:amount']", dom), 'content')?.trim() ?? '';
        }
      }
      
      price = price.replace("Discounted price: ", "");
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("CAD", "");
      price = price.replace("USD", "").trim();
    

      


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('TheNorthFaceParser.js error', err);
      return null;
    }
  }

}

export {TheNorthFaceParser};