// Try to parse current tab as a product
async function getCurrentTab() {
    let queryOptions = { active: true, lastFocusedWindow: true };
    // `tab` will either be a `tabs.Tab` instance or `undefined`.
    let [tab] = await chrome.tabs.query(queryOptions);

    // Restrict the fetch to pages for which parse works (product pages)
    
    console.log('Fetching tab:', tab.url);
    
    let parser = MerchantParserFactory.fromURL(tab.url);
    let request_info = {};
    if (typeof parser.getRequestInfo === 'function') {
      request_info = await parser.getRequestInfo()
      // request_info = {store_id:'3347'};
    }

    console.log('request_info', request_info);
    
    let product = {};
    // If the parser defines its own fetch function call it here (note fetch must return a parsed product)
    if (typeof parser.fetch === 'function') {
      product = await parser.fetch({request_info:request_info, product_url:tab.url})
    }
    // Otherwise do default fetch + parse
    else {
      let product_page_response = await fetch(tab.url);
      if (product_page_response.ok) {
        let html = await product_page_response.text();
        product = parser.parse(html, tab.url);
        
        // chrome.runtime.sendMessage(
        //   {
        //     message_type: 'popup_console_log_product',
        //     product: product
        //   },
        //   (response) => {
        //     console.log('received response from service worker');
        //   }
        // );

      }
    }    
    




    console.log(product);
    
    return tab;
}
getCurrentTab();

