import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class ArhausParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['variant', 'size']);
  }
  
  isProductPage(url) {
    // https://www.arhaus.com/products/luca-dining-table-1?variant=42351169536171
    let result = /\/products\//.test(url);
    return result;
  }

  getMerchant() {
    return 'arhaus';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
        selector: "h1[class='product__title body-x-large']",
        type: 'function',
        fun: function (doc, containing_span) {
          
          doc.querySelectorAll("h1[class='product__title body-x-large']").forEach((h1, index) => {
            h1.insertAdjacentElement('beforebegin', containing_span);
          });         
        },

      };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("title", dom) ?? '')?.trim();
      // title = " " + title;

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:image']", dom), 'content')?.trim() ?? '';

      // price
      let price_match = html.match(/\"price\"\:\"([\d\.]+)\"\,\"sku\"/);
      let price = price_match?.[1] ?? '';
      if(price == '') {
        price = domutils.getAttributeValue(CSSselect.selectOne("meta[property='product:price:amount']", dom), 'content')?.trim() ?? '';
      }
      
      
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('ArhausParser.js error', err);
      return null;
    }
  }

}

export {ArhausParser};