import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class LululemonUkParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
      // return ParserUtilities.filterUrlParameters(url, []);
      const urlObj = new URL(url);
      const params = urlObj.searchParams;

      // Create a new URLSearchParams object to store filtered params
      const filteredParams = new URLSearchParams();

      // Iterate through all parameters
      for (const [key, value] of params.entries()) {
          if (key.startsWith('dwvar_')) {
              filteredParams.append(key, value);
          }
      }

      // Construct the new URL with filtered parameters
      urlObj.search = filteredParams.toString();

      return urlObj.toString();
    }
  
  isProductPage(url) {
    // https://shop.lululemon.com/p/womens-leggings/Align-Pant-2/_/prod2020012?color=30699&sz=6
    let result = /\/p\//.test(url);
    return result;
  }

  getMerchant() {
    return 'lululemonUk';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
      selector: "h1",
      insertAdjacentPosition: "afterend",
    };
  }

  

  parse(html, url) {
    try {
      const dom = htmlparser2.parseDocument(html);
      // get title, link, merchant_product_id, image_link, price (is shipping diff than pickup?), coupon, details, specifications
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();
      title = 'Lululemon ' + title;

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:image']", dom), 'content')?.trim() ?? '';

      // price
      // if contains price range (because parent level product)
      if(html.includes('"price":"[')) {
        return null;
      }


      let price = domutils.textContent(CSSselect.selectOne("span[class='cta-price-value'] span span", dom) ?? '')?.trim();

      price = price.replace("£", "");
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
  
      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    }
    catch (err) {
      console.log('LululemonUkParser.js error', err);
      return null;
    }
  }

}

export {LululemonUkParser};