import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class PacsunParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    const urlObj = new URL(url);
    const params = urlObj.searchParams;

    // Create a new URLSearchParams object to store filtered params
    const filteredParams = new URLSearchParams();

    // Iterate through all parameters
    for (const [key, value] of params.entries()) {
        if (key.startsWith('dwvar_')) {
            filteredParams.append(key, value);
        }
    }

    // Construct the new URL with filtered parameters
    urlObj.search = filteredParams.toString();

    return urlObj.toString();
  }
  
  isProductPage(url) {
    // https://www.pacsun.com/pacsun/bella-light-indigo-denim-skirt-0840454210029.html?dwvar_0840454210029_color=349&tileCgid=womens
    let result = /\-[\d]+\.html/.test(url);
    return result;
  }

  getMerchant() {
    return 'pacsun';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
      selector: "h1",
      type: 'function',
      fun: function (doc, containing_span) {
        
        doc.querySelectorAll("h1").forEach((h1, index) => {
          h1.insertAdjacentElement('afterend', containing_span);
        });         

      },

    };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("img[data-image-index='0']", dom), 'srcset')?.trim() ?? '';
            image_link = image_link.split(" ")[0];

      // price
      let price_node = CSSselect.selectOne("span[class*='bfx-sale-price']", dom) ?? '';
      let price = domutils.getAttributeValue(CSSselect.selectOne("span[class*='bfx-list-price']", dom), 'content')?.trim() ?? '';
      if(price_node != '') {
        price = domutils.getAttributeValue(price_node, 'content')?.trim() ?? '';
      }
      
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('PacsunParser.js error', err);
      return null;
    }
  }

}

export {PacsunParser};