import he from 'he';
const CSSselect = require("css-select");

export function findClosestParent(node, selector) {
    let current = node;
    // Traverse up the tree using the .parent property
    while (current) {
        // Check if the current node matches the selector
        if (CSSselect.is(current, selector)) {
            return current;
        }
        current = current.parent;
    }
    return null; // No match found
}

export function objectFlip(obj) {
  return Object.keys(obj).reduce((ret, key) => {
    ret[obj[key]] = key;
    return ret;
  }, {});
};

export function getCookie(name) {
  let cookies = document.cookie.split("; ");
  for (let cookie of cookies) {
      let [key, value] = cookie.split("=");
      if (key === name) {
          return decodeURIComponent(value);
      }
  }
  return null; // Return null if cookie not found
}

export function replaceAllObjKeys(obj) {
  // if (Array.isArray(obj)) {
  //   for (let i = 0; i < obj.length; i++) {
  //     replaceAllObjKeys(obj[i]);
  //   }
  // }
  if (typeof obj === "object") {
      for (const key in obj) {
      const newKey = key.toLowerCase();
      obj[newKey] = obj[key];
      if (key !== newKey) {
          delete obj[key];
      }
      replaceAllObjKeys(obj[newKey]);
      }
  }

  return obj;
};


export function filterUrlParameters(url, whitelist) {
  const urlObj = new URL(url);
  const params = new URLSearchParams();

  // Add only the whitelisted parameters in order
  whitelist.forEach(param => {
      const value = urlObj.searchParams.get(param);
      if (value !== null) {
          params.append(param, value);
      }
  });

  // Set the new search parameters in the specified order
  urlObj.search = params.toString();

  // Strip the hash tag
  urlObj.hash = '';

  return urlObj.toString();
}

export function elementReady(selector) {
  return new Promise((resolve, reject) => {
    const el = document.querySelector(selector);
    if (el) {
      resolve(el);
    }

    new MutationObserver((mutationRecords, observer) => {
      Array.from(document.querySelectorAll(selector)).forEach(element => {
        resolve(element);
        observer.disconnect();
      });
    })
    .observe(document.documentElement, {
      childList: true,
      subtree: true
    });
  });
}

export function getOperatingSystem() {
  const userAgent = navigator.userAgent;

  if (/Windows NT 10/.test(userAgent)) return "Windows 10/11";
  if (/Windows NT 6\.3/.test(userAgent)) return "Windows 8.1";
  if (/Windows NT 6\.2/.test(userAgent)) return "Windows 8";
  if (/Windows NT 6\.1/.test(userAgent)) return "Windows 7";
  // if (/Macintosh/.test(userAgent) && 'ontouchend' in document) return "iPad";
  if (/iPad/.test(userAgent)) return "iPad";
  if (/iPhone/.test(userAgent)) return "iPhone";
  if (/Macintosh|Mac OS X/.test(userAgent)) return "mac";
  if (/Android/.test(userAgent)) return "Android";
  if (/Linux/.test(userAgent)) return "Linux";
  if (/CrOS/.test(userAgent)) return "Chrome OS";
  
  return "Unknown OS";
}

export function safeDecode(str) {
  if (!/&[a-zA-Z0-9#]+;/.test(str)) {
    return str;
  }
  const decoded = he.decode(str);
  return decoded !== str ? decoded : str;
}



/**
 * Recursively searches a data structure (object or array) for a specific key name
 * and returns the corresponding value if found.
 *
 * It handles arrays, objects, and gracefully ignores primitives (strings, numbers, null, etc.).
 *
 * @param {any} data - The data structure to search (can be an object, array, or primitive).
 * @param {string} keyName - The name of the key to find.
 * @returns {any | null} The value of the found key, or null if the key is not found.
 */
export function deepSearch(data, keyName) {
    // Base Case 1: If data is null or not an object (i.e., a primitive like string, number, undefined),
    // it cannot contain nested keys, so we terminate this branch.
    if (typeof data !== 'object' || data === null) {
        return null;
    }

    // Case 1: Handle Arrays
    if (Array.isArray(data)) {
        // Iterate over each item in the array and recursively search it.
        for (const item of data) {
            const foundValue = deepSearch(item, keyName);
            // If the recursive call found the key, return the value immediately.
            if (foundValue !== null) {
                return foundValue;
            }
        }
    }
    // Case 2: Handle Objects
    else {
        // First, check if the key is present in the current object level.
        if (data.hasOwnProperty(keyName)) {
            // Key found! Return the value associated with that key.
            return data[keyName];
        }

        // If not found at this level, recursively search nested properties.
        for (const key in data) {
            // Ensure we are only checking properties owned by the object (not prototype chain).
            if (data.hasOwnProperty(key)) {
                const foundValue = deepSearch(data[key], keyName);
                // If the recursive call found the key, return the value immediately.
                if (foundValue !== null) {
                    return foundValue;
                }
            }
        }
    }

    // Base Case 2: If the key was not found after checking this data structure and all its children.
    return null;
}