import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class EverlaneParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['variant']);
  }
  
  isProductPage(url) {
    // https://www.everlane.com/products/womens-new-fatigue-barrel-pant-black?collection=womens-sale
    let result = /\/products\//.test(url);
    return result;
  }

  getMerchant() {
    return 'everlane';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
        selector: "h1",
        type: 'function',
        fun: function (doc, containing_span) {
          
          doc.querySelectorAll("h1").forEach((h1, index) => {
            h1.insertAdjacentElement('afterend', containing_span);
          });         
        },

      };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("title", dom) ?? '')?.trim();
      title = title.replace(' – Everlane', '');
      title = "Everlane " + title;

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:image']", dom), 'content')?.trim() ?? '';

      // price
      let price_match = Array.from(html.matchAll(/\"convertedPrice\"\:([^\,]+)/g));
      // html.matchAll(/\"convertedPrice\"\:([^\,]+)/g);
      console.log('price_match', price_match);
      // let price = price_match?.[1] ?? '';

      let price = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:price:amount']", dom), 'content')?.trim() ?? '';
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
    
       // "convertedPrice":45,


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('EverlaneParser.js error', err);
      return null;
    }
  }

}

export {EverlaneParser};