import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class BestBuyCaParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['skuId']);
  }

  isProductPage(url) {
    // https://www.bestbuy.com/site/tcl-98-class-qm7-series-4k-uhd-hdr-qd-mini-led-smart-google-tv-2024/6580694.p?skuId=6580694
    // https://www.bestbuy.com/site/tcl-55-class-qm7-series-4k-uhd-hdr-qd-mini-led-smart-google-tv-2024/6579459.p?skuId=6579459    // 

    let result = /\/product\//.test(url);
    console.log('is product page?', result);
    return result;
  }

  getMerchant() {
    return 'bestbuyca';
  }

  /*
  <script>.+?({.+?})(?=<\/script>)


  color list:
  ul id="product-page-color-swatches"
  li...

  size list:
  ul id="size-filter-product-page-option-list"
  li...
  */

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
    
    let result = url.match(/\/s\/.*?\/(\d+)/); // the matches the parent level id, we'll inject the child id after
    return result?.[1];
  }

  getAddAlertInjection() {
    return {
      time_delay: 2500,
      type: 'function',
      // monitor_removal: true,
      fun: function (doc, containing_span) {

        let titleBlock = doc.querySelector("h1");
        if (titleBlock!=null) {
          titleBlock.insertAdjacentElement('afterend', containing_span);
        }

        console.log('entered getAddAlertInjection');
        // Fetch the HTML
        let fetch_options = {
          method: 'GET',
            headers: {'Content-Type': 'application/json;charset=utf-8'}
        };
        try {
          let product_page_response =
            fetch(window.location.href, fetch_options).then( response => response.text() )
            .then( html => {
              console.log('html fetched from addAlertInjection');
              
              let variant_info = null;

              // Look for one format first
              variant_info = html.match(/<script type="application\/json" id="shop-product-variations-\d+-json">(.*?)<\/script>/);
              if (variant_info!=null) {
                variant_info = JSON.parse(variant_info[1]);
              }
              else {
                variant_info = html.match(/"componentId":"product-variations".*?({.*?})"/); // the matches the parent level id, we'll inject the child id after
                if (variant_info==null) {
                  return
                }
                variant_info = JSON.parse(`"${variant_info[1]}"`);
                variant_info = JSON.parse(variant_info);
              }
              console.log('variant_info', variant_info);

              /*
              app:
                categories[]:
                  {
                    displayName
                    id
                    rawName
                    type
                    variations[]:
                      {name, displayStatus, variationSku}
                  }

              */

              // Attach an event listener to a parent container or the document
              document.addEventListener('click', event => {
                // Check if the click is inside an element with class "item c-carousel-item"
                const carouselItem = event.target.closest('.item.c-carousel-item, variation-carousel-redesign');
                
                
                if (carouselItem) {
                  console.log('Descendant clicked:', event.target);
                  console.log('the clicked on text was', event.target.textContent);
                  // Find closest parent with class = variation-carousel
                  // Find variation-header -> h2
                  // strip out trailing : and space from end
                  

                  console.log('testing', event.target.closest('.variation-carousel, .pdp-redesign-variation'));


                  let option_name = event.target.closest('.variation-carousel, .pdp-redesign-variation').querySelector('.variation-header h2').textContent.replace(/:\s*$/, '');
                  if (option_name==null) {
                    console.log('option_name is null');
                    return;
                  }
                  console.log('the option name being selected is', option_name);
                  console.log('closest header span', event.target.closest('.variation-carousel, .pdp-redesign-variation').querySelector('.variation-header > span, .variation-header > div'));

                  let option_value = event.target.closest('.variation-carousel, .pdp-redesign-variation').querySelector('.variation-header > span, .variation-header > div').textContent.replace(/ - Unavailable Nearby$/, '');
                  if (option_value==null) {
                    console.log('option_value is null');
                    return;
                  }
                  console.log('the option value is', option_value);

                  // use option name to find offset in categories array
                  let categories = null;
                  if (variant_info.hasOwnProperty('categories')) {
                    categories = variant_info['categories'];
                  }
                  else if (variant_info.hasOwnProperty('app') && variant_info['app'].hasOwnProperty('categories') ) {
                    categories = variant_info['app']['categories']
                  }
                  else {
                    console.log('categories is null');
                    return;
                  }
                  let category = categories.find(obj => obj.displayName === option_name);
                  if (category==null) {
                    console.log('category is null');
                    return;
                  }
                  console.log('the found category is', category);


                  // use the value of the option to get the offset into the variations array
                  let variant = category.variations.find(obj => obj.name === option_value);
                  if (variant==null) {
                    console.log('variant is null');
                    return;
                  }
                  console.log('the found variant was', variant);

                  // variant.variationSku;
                  let url = window.location.href
                  url = url.substring(0, url.lastIndexOf('/')) + '/' + variant.variationSku + '.p?skuId=' + variant.variationSku;
                  window.history.replaceState({}, "", url);

                }

              });


              // On any click event within those carousels, grab the new selected values, reference them to get the variant id, update the URL
              // watch URL change true
              
            });
        }
        catch(err) {
          console.log('Could not fetch for alert from product page', err);
          return null;
        }

        console.log('DONE FOR NOW');
        return;        
      },
      
      // selector: "#product-page-product-title-lockup",
      // selector: "h1",
      selector: "h1",
      // insertAdjacentPosition: "afterbegin",
    };
  }
  

  parse(html, url) {
    try {
      const dom = htmlparser2.parseDocument(html);
      // get title, link, merchant_product_id, image_link, price (is shipping diff than pickup?), coupon, details, specifications
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();
      // link
      let link = this.normalizeUrl(url);
      // merchant_product_id 
      let merchant_product_id = link;
      // image_link
      let image_link = CSSselect.selectOne("link[as='image']", dom)
      if (image_link!=null) {
        image_link = domutils.getAttributeValue(image_link, 'href')?.trim() ?? '';
      }
      
      let price = domutils.textContent(CSSselect.selectOne("div[class*='isSelected'] p[class*='price']", dom) ?? '')?.trim();
      if(price=='') {
        let price_match2 = html.match(/\"priceWithoutEhf\"\:([\d\.]+)\,\"/);
        price = price_match2?.[1] ?? '';
        console.log('entered price_match2', price_match2);
      }


      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
      
  
      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    }
    catch (err) {
      console.log('BestBuyCaParser.js error', err);
      return null;
    }
  }

}

export {BestBuyCaParser};