import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class CrateAndBarrelParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, []);
  }
  
  isProductPage(url) {
    // https://www.crateandbarrel.com/nosara-floral-linen-blend-napkin/s420237
    let result = /\/s[0-9]+$/.test(url);
    return result;
  }

  getMerchant() {
    return 'crateandbarrel';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
        selector: "h1",
        type: 'function',
        fun: function (doc, containing_span) {
          
          doc.querySelectorAll("h1").forEach((h1, index) => {
            h1.insertAdjacentElement('afterend', containing_span);
          });         
        },

      };
  }

  

  parse(html, url) {
    try {
      const dom = htmlparser2.parseDocument(html);
      // get title, link, merchant_product_id, image_link, price (is shipping diff than pickup?), coupon, details, specifications
      
      // title
      let title = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:title']", dom), 'content')?.trim() ?? '';
      title = title.replace(" + Reviews", '');
      title = title.replace(" | Crate & Barrel", '');

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:image']", dom), 'content')?.trim() ?? '';

      // price
      let price = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:price:amount']", dom), 'content')?.trim() ?? '';
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
  
      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    }
    catch (err) {
      console.log('CrateAndBarrelParser.js error', err);
      return null;
    }
  }

}

export {CrateAndBarrelParser};