import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class HMParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, []);
  }
  
  isProductPage(url) {
    // https://www2.hm.com/en_us/productpage.1245392001.html
    let result = /\/productpage\./.test(url);
    return result;
  }

  getMerchant() {
    return 'hm';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
      selector: "main h1",
      insertAdjacentPosition: "afterend",
    };
  }

  

  parse(html, url) {
    try {
      const dom = htmlparser2.parseDocument(html);
      // get title, link, merchant_product_id, image_link, price (is shipping diff than pickup?), coupon, details, specifications
      
      // title
      let title = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:title']", dom), 'content')?.trim() ?? '';
      title = title.replace(' | H&M US', '');

      // link
      let link = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:url']", dom), 'content')?.trim() ?? '';

      // merchant_product_id
      let merchant_product_id = this.normalizeUrl(link);

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:image']", dom), 'content')?.trim() ?? '';

      // price
      let price_match = html.match(/"price"\: \"([^"]+)"/);
      let price = price_match?.[1] ?? '';
      if(price == '') {
        price_match = html.match(/\"price\"\:\"([\d\.\,]+)\"\,\"/);
        price = price_match?.[1] ?? '';
        if(price == '') {
          price_match = html.match(/"price"\: ([^}]+)}/);
          price = price_match?.[1] ?? '';
      }
      }

      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
  
      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    }
    catch (err) {
      console.log('HMParser.js error', err);
      return null;
    }
  }

}

export {HMParser};