import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class SilkAndSnowParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['variant', 'size', 'type', 'product_type', 'colour', 'depth', 'arm' ]);
  }
  
  isProductPage(url) {
    // https://www.SilkAndSnow.com/en-us/product/twilight-the-cullen-house-21354
    let result = /silkandsnow.com/.test(url);
    return result;
  }

  getMerchant() {
    return 'silkandsnow';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
        selector: "h1[class='section_desktop']",
        insertAdjacentPosition: "afterend",
      };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:title']", dom), 'content')?.trim() ?? '';
      title = title.replace( '- Silk & Snow', '').trim();

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("link[rel='preload'][ type='image/jpeg']", dom), 'href')?.trim() ?? '';

      // price
      let price_match = html.match(/\"price\"\:"([\d\.]+)"\,\"/);
      let price = price_match?.[1] ?? '';
      if(price=='') {
        price = domutils.getAttributeValue(CSSselect.selectOne(".pp-message", dom), 'data-pp-amount')?.trim() ?? '';
      }
      
      
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();


    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('SilkAndSnowParser.js error', err);
      return null;
    }
  }

}

export {SilkAndSnowParser};