import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class AdvanceAutoPartsParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['variant', 'size']);
  }
  
  isProductPage(url) {
    // https://shop.advanceautoparts.com/p/rain-x-2-in-1-all-season-windshield-washer-fluid-improved-water-beading-1-gallon-5066517/7150024-P?source=certona
    let result = /\/p\//.test(url);
    return result;
  }

  getMerchant() {
    return 'advanceautoparts';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
        selector: "h1[class*='css']",
        insertAdjacentPosition: "afterend",
      };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("title", dom) ?? '')?.trim();
      title = title.replace(' - Advance Auto Parts', '');

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:image']", dom), 'content')?.trim() ?? '';

      // price
      let price_match = html.match(/\"salePrice\"\:([\d\.]+)\,\"/);
      let price = price_match?.[1] ?? '';
      if(price == '') {
        
      }
      price = price.replace(",", "");

      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('AdvanceAutoPartsParser.js error', err);
      return null;
    }
  }

}

export {AdvanceAutoPartsParser};