import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class BassProParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['variant', 'size']);
  }
  
  isProductPage(url) {
    // https://www.basspro.com/p/bass-pro-shops-100188644
    let result = /\/(p|shop)\//.test(url);
    return result;
  }

  getMerchant() {
    return 'basspro';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  // getAddAlertInjection() {
  //   return {
  //       selector: "div[class*='styles_BazaarVoiceWrapper']",
  //       insertAdjacentPosition: "beforebegin",
  //     };
  // }

  getAddAlertInjection() {
    return {
      type: 'function',
      fun: function (doc, containing_span) {
        let titleBlock = doc.querySelector("div[class*='styles_BazaarVoiceWrapper']");
        if (titleBlock!=null) {
          titleBlock.insertAdjacentElement('beforebegin', containing_span);
        }
        else {
          console.log('brian entered else');
          let nodes = doc.querySelectorAll("h1");
          nodes.forEach(function(element, index, array) {
            element.insertAdjacentElement('afterend', containing_span);
          });
        }

        // clean up time beacon
        let time_beacon = document.getElementById("pl_extension_time_beacon");
        time_beacon.parentNode.removeChild(time_beacon);
      },
      selector: "#pl_extension_time_beacon",
      
      // insertAdjacentPosition: "afterbegin",
    };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("title", dom) ?? '')?.trim();
      title = title.replace(' | Bass Pro Shops', '');
      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:image']", dom), 'content')?.trim() ?? '';

      // price
      let price_match = html.match(/\,\"price\"\:\"([\d\.\,]+)\"\,/);
      let price = price_match?.[1] ?? '';
      if(price == '') {
        price = domutils.getAttributeValue(CSSselect.selectOne("input[id*='ProductInfoPrice']", dom), 'value')?.trim() ?? '';
      }

      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('BassProParser.js error', err);
      return null;
    }
  }

}

export {BassProParser};