import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class LgParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['variant', 'size']);
  }
  
  isProductPage(url) {
    // 
    let result = /lg\.com(?:\/[^\/]*){3}\b/.test(url);
    return result;
  }

  getMerchant() {
    return 'lg';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
        selector: "h2[class*='MuiTypography-']",
        insertAdjacentPosition: "afterend",
      };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();
      // title = " " + title;

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link =  '';
      
      const links = CSSselect.selectAll("link[rel='preload']", dom);
      for (const link of links) {
        const srcSet = domutils.getAttributeValue(link, 'imagesrcset')?.trim() ?? '';
        // console.log("Found imageSrcSet:", srcSet);
        if (srcSet) {
          image_link = srcSet.split(' ')[0]
          if(!image_link.includes('360vr') && !image_link.includes('youtube.com')) {
            break; 
          }
        }
      }



      // console.log('image_link1', image_link);
      // image_link = image_link.split(' ')[0]
      // console.log('image_link2', image_link);

      // price
      let price = domutils.textContent(CSSselect.selectOne("h4[class*='MuiTypography-']", dom) ?? '')?.trim();

      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('LgParser.js error', err);
      return null;
    }
  }

}

export {LgParser};