import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class TroubadourGoodsParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['variant', 'size']);
  }
  
  isProductPage(url) {
    // https://www.troubadourgoods.com/products/iphone-17-case?variant=47449089376488
    let result = /\/products\//.test(url);
    return result;
  }

  getMerchant() {
    return 'troubadourgoods';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
        selector: "h1",
        insertAdjacentPosition: "beforeend",
      };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:image']", dom), 'content')?.trim() ?? '';

      // price
      let price ='';
      let emptyClasses = CSSselect.selectAll("div[class='']", dom) ?? '';
      console.log(emptyClasses);
      for(let i=0; i<emptyClasses.length;i++) {
        // console.log('text content', domutils.textContent(emptyClasses[i]));
        if(domutils.textContent(emptyClasses[i]).includes('$')) {
          price = domutils.textContent(emptyClasses[i]);
          break;
        }
      }


      if(price == '') {
        let price_match = html.match(/Offer\"\,\"price\"\:\"([\d\.]+)\"\,/);
        let price = price_match?.[1] ?? '';
      }

      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();



      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('TroubadourGoodsParser.js error', err);
      return null;
    }
  }

}

export {TroubadourGoodsParser};