import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class KohlsParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['color', 'size']);
  }
  
  isProductPage(url) {
    // https://www.kohls.com/product/prd-7597715/celebrate-together-halloween-2-pc-bone-salad-servers-set.jsp
    let result = /\/product\//.test(url);
    return result;
  }

  getMerchant() {
    return 'kohls';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
        selector: "h1",
        insertAdjacentPosition: "afterend",
      };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      // kohl's sometimes has URLs longer than 256 chars
      let merchant_product_id = url.match(/prd-(\d+)/)?.[1] ?? link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("meta[itemprop='image']", dom), 'content')?.trim() ?? '';

      // price
      let price = domutils.getAttributeValue(CSSselect.selectOne("meta[itemprop='price']", dom), 'content')?.trim() ?? '';
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('KohlsParser.js error', err);
      return null;
    }
  }

}

export {KohlsParser};