import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class ChewyParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, []);
  }

  isProductPage(url) {
    // https://www.chewy.com/american-journey-grain-free-chicken/dp/317680
    let result = /\/dp\//.test(url);
    return result;
  }

  getMerchant() {
    return 'chewy';
  }

  merchantIdFromURL(url, html='') {
    let result = url.match(/dp\/([\d]+)($|\?)/);
    return result?.[1];
  }

  getAddAlertInjection() {
    return {
      selector: "div[data-testid='product-title']",
      insertAdjacentPosition: "afterend",
    };
  }

  

  parse(html, url) {
    try {
      const dom = htmlparser2.parseDocument(html);
      // get title, link, merchant_product_id, image_link, price (is shipping diff than pickup?), coupon, details, specifications
      
      // title
      let title = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:title']", dom), 'content')?.trim() ?? '';
      title = title.replace(" - Chewy.com", "");

      // link - will need to get current URL (and potentially remove other URL parameters) from fetch 
      let link = this.normalizeUrl(url);

      //   let link = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:url']", dom), 'content')?.trim() ?? '';
      // get from link later 
      let merchant_product_id = link.split("/").pop();
      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("link[as='image']", dom), 'href')?.trim() ?? '';
      
      // price 
      let price = domutils.textContent(CSSselect.selectOne("div[data-testid='buy-once-selector'] span[class='kib-product-price__label']", dom) ?? '')?.trim();
      if(price == '') {
        price = domutils.textContent(CSSselect.selectOne("span[class='kib-product-price__label']", dom) ?? '')?.trim();
        price = price.split("(")[0];
      }

      price = price.replace("CA ", "");
      price = price.replace("$", "");
      price = price.replace("Chewy Price", "");

  
      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    }
    catch (err) {
      console.log('ChewyParser.js error', err);
      return null;
    }
  }

}

export {ChewyParser};