import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class NordstromRackParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['color','size', 'width']);
  }

  isProductPage(url) {
    // https://www.nordstromrack.com/s/bcbg-max-azria-belted-double-breasted-faux-leather-trench-coat/7779485?origin=coordinating-7779485-0-2-HP_STRATEGIC_BRANDS_RACK-recbot-browse_results_interleave_rack&recs_placement=HP_STRATEGIC_BRANDS_RACK&recs_strategy=browse_results_interleave_rack&recs_source=recbot&recs_page_type=home&recs_seed=0&color=BLACK
    let result = /\/s\//.test(url);
    return result;
  }

  getMerchant() {
    return 'nordstromrack';
  }

  /*
  <script>.+?({.+?})(?=<\/script>)


  color list:
  ul id="product-page-color-swatches"
  li...

  size list:
  ul id="size-filter-product-page-option-list"
  li...
  */

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
    
    let result = url.match(/\/s\/.*?\/(\d+)/); // the matches the parent level id, we'll inject the child id after
    return result?.[1];
  }

  getAddAlertInjection() {
    return {
      time_delay: 2000,
      type: 'function',
      fun: function (doc, containing_span) {
        let updateCurrentUrlParameter = function(paramName, paramValue) {
          const url = new URL(window.location.href);
          const params = url.searchParams;
        
          if (paramValue === null || paramValue === undefined) {
            params.delete(paramName);
          } else {
            params.set(paramName, paramValue);
          }
        
          // Update the browser's URL
          window.history.replaceState({}, "", url);
        }

        // Grab the product information
        let product_info = {};
        let scripts = doc.querySelectorAll("script");
        for (let i = 0; i < scripts.length; i++) {;
          let match = scripts[i].textContent.match(/window.__INITIAL_CONFIG__ = (.*})$/);
          if (match!=null && match.length>=2) {
            product_info = JSON.parse(match[1]);
          }
        }
        console.log('finished regex against initial_config');

        // console.log(product_info);

        // sellingEssentials
        // consumers
        //   product-page-7146878
        //     skuFilterGroups
        //       color
        //         options [] of {}
        //           displayValue (Green Park)
        //           id (302)

        let product_info_skuFilterGroups = product_info['sellingEssentials']['consumers'];
        let tmp_keys = Object.keys(product_info_skuFilterGroups);
        // console.log(product_info_skuFilterGroups)
        // console.log(tmp_keys)
        let color_options = product_info_skuFilterGroups[tmp_keys[0]]['skuFilterGroups']['color']?.['options'];
        let size_options = product_info_skuFilterGroups[tmp_keys[0]]['skuFilterGroups']['size'];
        let width_options = product_info_skuFilterGroups[tmp_keys[0]]['skuFilterGroups']['width']?.['options'];
        console.log(color_options);
        console.log(size_options);
        console.log(width_options);



        // Update URL on color variant change
        let color_lis = doc.querySelectorAll("#product-page-color-swatches li");
        color_lis.forEach((currentValue, currentIndex, listObj) => {
          // Lookup the color code for this color value
          let img = currentValue.querySelector('img');
          // console.log(img);
          if (img!=null) {
            let index = color_options.findIndex(obj => obj['displayValue'] === img.getAttribute('title'));
            // console.log('Found color option!', color_options[index]);
            currentValue.onclick = function() {
              console.log('clicked on color li', index);
              updateCurrentUrlParameter('color', color_options[index]['id']);
            }

            // Check to see if this li has an svg (the checkbox), if so update the urlparam for color
            let svg = currentValue.querySelector('svg');
            if (svg!=null) {
              updateCurrentUrlParameter('color', color_options[index]['id']);
            }
          } 
        });

        // If size exists
        if (size_options!=null) {
          // Setup onclick for the lis, but they don't exist yet so bind to parent
          doc.querySelector('#size-filter-product-page-anchor').parentElement.addEventListener("click", (event) => {
            console.log('clicked on sub anchor');
            console.log(event);

            // Ignore this, the drop down was clicked on
            if (event.target.id=='size-filter-product-page-anchor') {
              
            }
            // Otherwise a subchild of an LI was clicked
            else {
              // Find the parent LI
              let li = event.target.closest('li');
              if (li!=null) {
                // Find all child nodes to test for text equivalence
                let children = li.querySelectorAll('*'); // Select all descendants
                
                // Check each child element
                for (let child of children) {
                  
                  if (size_options?.['options']) {
                    let index = size_options['options'].findIndex(obj => obj['displayValue'] === child.textContent.trim());
                    if (index!=-1) {
                      console.log('Found a match for size');
                      console.log(size_options['options'][index]);
                      updateCurrentUrlParameter('size', size_options['options'][index]['id']);
                      break;
                    }
                  }
                  else if (size_options?.['optionGroups']) {
                    for (let group of size_options['optionGroups']) {
                      let index = group['options'].findIndex(obj => obj['displayValue'] === child.textContent.trim());
                      if (index!=-1) {
                        console.log('Found a match for size');
                        console.log(group['options'][index]);
                        updateCurrentUrlParameter('size', group['options'][index]['id']);
                        break;
                      }
                    }
                  }

                } // End check each child element
              } // End li parent exists
            }

          });
        }

        // If width exists
        if (width_options!=null) {
          // Check if a width is already set
          let preset_nodes = doc.querySelector('#width-filter-product-page-anchor').querySelectorAll('*')
          // Check each child element
          let index = -1;
          for (let child of preset_nodes) {
              // if there's an element in the widths aray that matches
              index = width_options.findIndex(obj => obj['displayValue'] === child.textContent.trim());
              if (index != -1) {
                console.log('Found a match for width');
                break; // Found a match
              }
          }
          if (index!=-1) {
            console.log(width_options[index]);
            updateCurrentUrlParameter('width', width_options[index]['id']);
          }

          // Setup onclick for the lis, but they don't exist yet so bind to parent
          doc.querySelector('#width-filter-product-page-anchor').parentElement.addEventListener("click", (event) => {
            console.log('clicked on sub anchor');
            console.log(event);

            // Ignore this, the drop down was clicked on
            if (event.target.id=='width-filter-product-page-anchor') {
              
            }
            // Otherwise a subchild of an LI was clicked
            else {
              // Find the parent LI
              let li = event.target.closest('li');
              if (li!=null) {
                // Find all child nodes to test for text equivalence
                let children = li.querySelectorAll('*'); // Select all descendants
                // Check each child element
                let index = -1;
                for (let child of children) {
                    // if there's an element in the widths aray that matches
                    index = width_options.findIndex(obj => obj['displayValue'] === child.textContent.trim());
                    if (index != -1) {
                      console.log('Found a match for width');
                      break; // Found a match
                    }
                }
                if (index!=-1) {
                  console.log(width_options[index]);
                  updateCurrentUrlParameter('width', width_options[index]['id']);
                }
                else {
                  console.log('Did not find a match for width');
                }
              }
            }
          });
        }


        // Are all params present?
        let params_present = true;
        if (color_options!=null && !(new URL(window.location.href).searchParams.has('color')) ) {
          params_present=false;
        }
        if (size_options!=null && !(new URL(window.location.href).searchParams.has('size')) ) {
          params_present=false;
        }
        if (width_options!=null && !(new URL(window.location.href).searchParams.has('width')) ) {
          params_present=false;
        }

        if (params_present) {
          let titleBlock = doc.querySelector("#product-page-product-title-lockup");
          if (titleBlock!=null) {
            titleBlock.insertAdjacentElement('beforebegin', containing_span);
          }
        }


        
        // clean up time beacon
        let time_beacon = document.getElementById("pl_extension_time_beacon");
        time_beacon.parentNode.removeChild(time_beacon);
        
      },
      
      // selector: "#product-page-product-title-lockup",
      selector: "#pl_extension_time_beacon",

      
      // insertAdjacentPosition: "afterbegin",
    };
  }
  

  parse(html, url) {
    try {
      const dom = htmlparser2.parseDocument(html);
      // get title, link, merchant_product_id, image_link, price (is shipping diff than pickup?), coupon, details, specifications
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();
      // link
      let link = this.normalizeUrl(url);
      // merchant_product_id 
      let merchant_product_id = link;
      // image_link
      let image_link = CSSselect.selectOne("#gallery-item-container-zoom-0 img", dom)
      if (image_link!=null) {
        image_link = domutils.getAttributeValue(image_link, 'src')?.trim() ?? '';
      }
      else {
        image_link='';
      }
      
  
      // price priceMin : '1399.99',
      let price_match = html.match(/Current Price \$([\d\.]+)/);
      let price = price_match?.[1] ?? '';
      price = price.replace(",", "");
  
      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    }
    catch (err) {
      console.log('NordstromRackParser.js error', err);
      return null;
    }
  }

}

export {NordstromRackParser};