import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class VictoriasSecretParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['choice', 'genericId']);
  }
  
  isProductPage(url) {
    // https://bombas.com/products/women-s-solid-ankle-sock-white-medium?variant=white&size=m
    let result = /\-catalog/.test(url);
    return result;
  }

  getMerchant() {
    return 'victoriassecret';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
        selector: "h1",
        insertAdjacentPosition: "afterend",
      };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link_match = html.match(/"image":\s*\[\s*"([^"]+)"/);
      let image_link = image_link_match?.[1] ?? '';
      if(image_link != '') {
        image_link = 'https://'+image_link;
      }

      // price
      let price_match = html.match(/"price"\:([\d\.]+)\}/);
      let price = price_match?.[1] ?? '';

      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('VictoriasSecretParser.js error', err);
      return null;
    }
  }

}

export {VictoriasSecretParser};