import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class AdidasParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['forceSelSize']);
  }
  
  isProductPage(url) {
    // https://www.adidas.com/us/gazelle-indoor-shoes/IF6982.html?forceSelSize=M+6.5+%2F+W+7.5
    let result = /\/[\w]+\.html?/.test(url);
    return result;
  }

  getMerchant() {
    return 'adidas';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
      selector: "h1",
      type: 'function',
      fun: function (doc, containing_span) {
        
        doc.querySelectorAll("h1").forEach((h1, index) => {
          h1.insertAdjacentElement('afterend', containing_span);
        });         

      },

    };
  }

  
  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();
      title = "Adidas " + title;

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:image']", dom), 'content')?.trim() ?? '';

      // price
      let price = domutils.textContent(CSSselect.selectOne("div[data-testid*='main-price']", dom) ?? '')?.trim();
      price = price.replace("Sale price", "");
      price = price.replace("Price", "");
      
      price = price.replace("$", "");
      price = price.replace("£", "");
      price = price.replace("€", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('AdidasParser.js error', err);
      return null;
    }
  }

}

export {AdidasParser};