import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class OnrunningParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['variant']);
  }
  
  isProductPage(url) {
    // https://www.on.com/en-us/products/cloud-x-3-60/womens/white-black-shoes-60.98697?variant=7.5
    let result = /\/products\//.test(url);
    return result;
  }

  getMerchant() {
    return 'onrunning';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
      type: 'function',
      fun: function (doc, containing_span) {
        
        doc.querySelectorAll("div[class*='_titlePriceContainer_']").forEach((h1, index) => {
          h1.insertAdjacentElement('afterend', containing_span);
        });         

      },
      selector: "div[class*='_titlePriceContainer_']",

    };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("title", dom) ?? '')?.trim();
      title = title.replace(' | On United States', '');
      title = "On " + title;


      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("section[class*='_productGallery_'] source", dom), 'srcset')?.trim() ?? '';
      image_link = image_link.split(" ")[0];

      // price
      let price = domutils.textContent(CSSselect.selectOne("span[class*='_price_']", dom) ?? '')?.trim();
      
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
      price = price.replace("CAD ", "");
    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('OnrunningParser.js error', err);
      return null;
    }
  }

}

export {OnrunningParser};