import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class KmartAuParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['variant', 'size']);
  }
  
  isProductPage(url) {
    // https://www.kmart.com.au/product/79cm-extra-large-hard-case-luggage-43623600/
    let result = /\/product\//.test(url);
    return result;
  }

  getMerchant() {
    return 'kmartau';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
        selector: "h1",
        type: 'function',
        fun: function (doc, containing_span) {
          
          doc.querySelectorAll("h1").forEach((h1, index) => {
            h1.insertAdjacentElement('afterend', containing_span);
          });         
        },

      };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("img[class='img-active']", dom), 'srcset')?.trim() ?? '';
      let image_link_parts = image_link.split('?');
      image_link  = image_link_parts[0];


      // price
      let price = domutils.textContent(CSSselect.selectOne("span[class*='product-price-large']", dom) ?? '')?.trim();
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('KmartAuParser.js error', err);
      return null;
    }
  }

}

export {KmartAuParser};