import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class SsenseParser {
  watchURLChanges() {
    return false;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, []);
  }

  isProductPage(url) {
    // https://www.ssense.com/en-us/men/product/apc/off-white-fairfax-jeans/16877291
    let result = /\/product\//.test(url);
    return result;
  }

  getMerchant() {
    return 'ssense';
  }

  merchantIdFromURL(url, html='') {
    let result = url.match(/\/([\d]+)($|\?)/);
    return result?.[1];
  }

  getAddAlertInjection() {
    return {
      selector: "div[class='pdp-product-price__container']",
      insertAdjacentPosition: "afterend",
    };
  }

  

  parse(html, url) {
    try {
      const dom = htmlparser2.parseDocument(html);
      // get title, link, merchant_product_id, image_link, price (is shipping diff than pickup?), coupon, details, specifications
      
      // title
      let title = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:title']", dom), 'content')?.trim() ?? '';
      // link
      let link = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:url']", dom), 'content')?.trim() ?? '';
      // merchant_product_id 
      let merchant_product_id = this.merchantIdFromURL(link);
      // image_link
      let image_link_match = html.match(/"image"\:"([^"]+)"/);
      let image_link = image_link_match?.[1] ?? '';
      
      // price 
      // span class = product-price__price s-text
      let price = domutils.textContent(CSSselect.selectOne("span[class='product-price__price s-text']", dom) ?? '')?.trim();

      price = price.replace(",", "");
      price = price.replace("$", "");
      price = price.replace(" USD", "");
  
      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    }
    catch (err) {
      console.log('SsenseParser.js error', err);
      return null;
    }
  }

}

export {SsenseParser};