import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class MemoryExpressParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['variant', 'size']);
  }
  
  isProductPage(url) {
    // https://bombas.com/products/women-s-solid-ankle-sock-white-medium?variant=white&size=m
    let result = /\/Products\//.test(url);
    return result;
  }

  getMerchant() {
    return 'memoryexpress';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
        selector: "h1",
        insertAdjacentPosition: "afterend",
      };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("title", dom) ?? '')?.trim();
      title = title.replace(' - Memory Express Inc.', '');

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("div[data-component='C:Catalog:Product/Images'] img", dom), 'src')?.trim() ?? '';

      // price
      let price = domutils.textContent(CSSselect.selectOne("div[class*='GrandTotal']", dom) ?? '')?.trim();
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
      price = price.replace("Only", "").trim();
    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('MemoryExpressParser.js error', err);
      return null;
    }
  }

}

export {MemoryExpressParser};