import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class VuoriParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['objectId']);
  }
  
  isProductPage(url) {
    // https://vuoriclothing.com/products/womens-elevation-racerback-tank-rain-heather
    let result = /vuoriclothing\.com\/products\//.test(url);
    return result;
  }

  getMerchant() {
    return 'vuori';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
      selector: "div[data-testid='pdptop-title-price']",
      insertAdjacentPosition: "afterend",
    };
  }

  

  parse(html, url) {
    try {
      const dom = htmlparser2.parseDocument(html);
      // get title, link, merchant_product_id, image_link, price (is shipping diff than pickup?), coupon, details, specifications
      
      // title
      let title = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:title']", dom), 'content')?.trim() ?? '';

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link_match = html.match(/"image"\:"([^"]+)"/);
      let image_link = image_link_match?.[1] ?? '';
      

      // price
      let price_match = html.match(/"price"\:([^\,]+)\,/);
      let price = price_match?.[1] ?? '';
      if(price == '') {
        let price = domutils.textContent(CSSselect.selectOne("h3[data-testid='productdescriptionprice-price']", dom) ?? '')?.trim();
      }
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
      
  
      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    }
    catch (err) {
      console.log('VuoriParser.js error', err);
      return null;
    }
  }

}

export {VuoriParser};