import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class PrincessAutoParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['variant', 'size']);
  }
  
  isProductPage(url) {
    // https://bombas.com/products/women-s-solid-ankle-sock-white-medium?variant=white&size=m
    let result = /\/product\//.test(url);
    return result;
  }

  getMerchant() {
    return 'princessauto';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
        selector: ".product-title",
        insertAdjacentPosition: "afterend",
      };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title_match = html.match(/\,\"name\"\:\"(.*)\"\,\"description"/);
      let title = title_match?.[1] ?? '';

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
     let image_match = html.match(/\,\"image\"\:\"(.*)\"\,\"\@type\"/);
     let image_link = image_match?.[1] ?? '';
     image_link = image_link.replace(/\.jpg.*/, '.jpg');

      // price
      let price_match = html.match(/\,\"price\"\:([\d\.]+),/);
      let price = price_match?.[1] ?? '';
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('PrincessAutoParser.js error', err);
      return null;
    }
  }

}

export {PrincessAutoParser};