import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class LululemonParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['color', 'sz']);
  }
  
  isProductPage(url) {
    // https://shop.lululemon.com/p/womens-leggings/Align-Pant-2/_/prod2020012?color=30699&sz=6
    let result = /\/p\//.test(url);
    return result;
  }

  getMerchant() {
    return 'lululemon';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
      selector: "h1[class*='product-title']",
      insertAdjacentPosition: "afterend",
    };
  }

  

  parse(html, url) {
    try {
      const dom = htmlparser2.parseDocument(html);
      // get title, link, merchant_product_id, image_link, price (is shipping diff than pickup?), coupon, details, specifications
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();
      title = 'Lululemon ' + title;

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:image']", dom), 'content')?.trim() ?? '';

      // price
      let price_string = domutils.textContent(CSSselect.selectOne("div[class*='pdp-price-wrapper'] span[data-lll-pl='price']", dom) ?? '')?.trim();
      console.log('brian price_string', price_string);
      // extract first price
      const regex = /\d+(\.\d+)?/;
      const match = price_string.match(regex);
      let price = match ? match[0] : null;


      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
  
      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    }
    catch (err) {
      console.log('LululemonParser.js error', err);
      return null;
    }
  }

}

export {LululemonParser};