import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class OverstockParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['variant']);
  }
  
  isProductPage(url) {
    // https://www.overstock.com/products/valoria-3-drawer-gold-accent-nightstand-40244922?variant=45152427901087
    let result = /product\.html/.test(url);
    return result;
  }

  getMerchant() {
    return 'overstock';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
        selector: "h1",
        type: 'function',
        fun: function (doc, containing_span) {
          
          doc.querySelectorAll("h1").forEach((h1, index) => {
            h1.insertAdjacentElement('afterend', containing_span);
          });         
        },

      };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("img[loading='lazy']", dom), 'src')?.trim() ?? '';

      // price
      let price_match = html.match(/\,"price"\:"([\d\.]+)"\,/);
      let price = price_match?.[1] ?? '';
      if(price == '') {
        let price_match2 = html.match(/"\,"lowPrice"\:"([\d\.]+)"\}/);
        price = price_match2?.[1] ?? '';

      }


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('OverstockParser.js error', err);
      return null;
    }
  }

}

export {OverstockParser};