import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class EtsyParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['variation0', 'variation1', 'variation2']);
  }
  
  isProductPage(url) {
    // https://www.etsy.com/listing/1841478769/build-your-own-custom-charm?click_key=34004fde0a40e4be2929981c7d68d60486c2fe1c%3A1841478769&click_sum=ad95cf80&ref=hp_daily_deals-1&pro=1&sts=1&variation0=4992279262&variation1=4970831221
    let result = /\/listing\//.test(url);
    return result;
  }

  getMerchant() {
    return 'etsy';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  // getAddAlertInjection() {
  //   return {
  //       selector: "h1",
  //       insertAdjacentPosition: "afterend",
  //     };
  // }

  getAddAlertInjection() {
    return {
      type: 'function',
      fun: function (doc, containing_span) {
        let price = document.querySelector("div[data-buy-box-region='price'] p")?.textContent;
        console.log('injection price', price);
        // if contains price range return null, so won't inject
        if(price.includes('+')) {
          console.log('brian contains -');
          let titleBlock = doc.querySelector("title");
          titleBlock.insertAdjacentElement('afterend', containing_span);
          return null;
        }
       
          let titleBlock = doc.querySelector("h1");
          titleBlock.insertAdjacentElement('afterend', containing_span);

        return;
      },
      selector: "h1",
    };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:image']", dom), 'content')?.trim() ?? '';

      // price
      
      let price = domutils.textContent(CSSselect.selectOne("div[data-buy-box-region*='price'] p", dom) ?? '')?.trim();
      price = price.replace("Price:", "");
      price = price.trim();
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("Now", "").trim();
      price = price.replace("USD", "").trim();
      price = price.replace("CA", "").trim();
    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('EtsyParser.js error', err);
      return null;
    }
  }

}

export {EtsyParser};