import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class GncParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['variant']);
  }
  
  isProductPage(url) {
    // https://www.gnc.com/energy-drinks/582005.html#start=1
    let result = /\/[\d]+\.html/.test(url);
    return result;
  }

  getMerchant() {
    return 'gnc';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
        selector: "h1",
        insertAdjacentPosition: "afterend",
      };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("title", dom) ?? '')?.trim();
      title = title.replace(' | GNC', '')
      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:image']", dom), 'content')?.trim() ?? '';


      // price
      let price = domutils.getAttributeValue(CSSselect.selectOne("meta[property='product:price:amount']", dom), 'content')?.trim() ?? '';
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('GncParser.js error', err);
      return null;
    }
  }

}

export {GncParser};