import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class AllbirdsParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['size']);
  }
  
  isProductPage(url) {
    // https://www.allbirds.com/products/mens-tree-runners-rugged-beige?size=13
    let result = /\/products\//.test(url);
    return result;
  }

  getMerchant() {
    return 'allbirds';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
        selector: "div[data-pdp-product-info]",
        type: 'function',
        fun: function (doc, containing_span) {
          
          doc.querySelectorAll("div[data-pdp-product-info]").forEach((h1, index) => {
            h1.insertAdjacentElement('beforebegin', containing_span);
          });         
        },

      };
  }

  

  parse(html, url) {
    try {
      let link = this.normalizeUrl(url);
      let merchant_product_id = link;
      let title = '';
      let image_link = '';
      let price = '';
    

      const dom = htmlparser2.parseDocument(html);
      // get title, link, merchant_product_id, image_link, price (is shipping diff than pickup?), coupon, details, specifications
      let schema = {};
      let schema_select_all = CSSselect.selectAll("script[type='application/ld+json']", dom);
      // console.log('schema_select_all', schema_select_all);
      schema_select_all.forEach(element => {
        // console.log('element', element);
        schema = domutils.textContent(element)?.trim() ?? '';;
        let schema_json = JSON.parse(schema);
        // console.log('schema_json', schema_json);
        
        // iterate over schema_json until you find the specific URL

        // Check if it's a ProductGroup schema
        if (schema_json['@type'] === 'ProductGroup' && Array.isArray(schema_json.hasVariant)) {
          // console.log('ProductGroup Schema:', schema_json); // Log the parsed data

          // check if parent level url matches
          if (schema_json.offers.url === link) {
            console.log('Matching link found: parent URL!');

            if (Array.isArray(schema_json.image)) {
              image_link = schema_json.image[0];
            }
            else {
              image_link = schema_json.image ?? '';
            }

            title = "Allbirds "+schema_json.name ?? '';
            price = schema_json.offers.price ?? '';
          }


          // Iterate through each variant in hasVariant
          for (let variant of schema_json.hasVariant) {
            // Ensure variant has an 'offers' field
            if (variant.offers && variant.offers.url === link) {
              console.log('Matching link found: variant!');

              if (Array.isArray(variant.image)) {
                image_link = variant.image[0];
              }
              else {
                image_link = variant.image ?? '';
              }

              title = "Allbirds "+variant.name ?? '';
              price = variant.offers.price ?? '';
            }
          }
        }
        else {
          console.log('not ProductGroup, instead: '+ schema_json['@type']);
        }
      });
  
     console.log('schema', schema);
     let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
      /*



      // title
      let title = domutils.getAttributeValue(CSSselect.selectOne("meta[name='title']", dom), 'content')?.trim() ?? '';
      title = title.replace(' | Stuart Weitzman', '');
        title = 'Stuart Weitzman '+title;
      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("link[as='image']", dom), 'href')?.trim() ?? '';

      // price
      let price_match = html.match(/"cm_txt_pdt_price">\$([^\<]+)/);
      let price = price_match?.[1] ?? '';
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    */
    }
    catch (err) {
      console.log('AllbirdsParser.js error', err);
      return null;
    }
  }

}

export {AllbirdsParser};