import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class OreillyAutoParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['variant', 'size']);
  }
  
  isProductPage(url) {
    // https://www.oreillyauto.com/detail/c/brakebest-select-brake-pads/brakes/brake-pads---shoes/a349129f45da/brakebest-select-front-ceramic-brake-pads/bb22/sc1063?pos=0
    let result = /\/detail\/c\//.test(url);
    return result;
  }

  getMerchant() {
    return 'oreillyauto';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
        selector: "h1",
        insertAdjacentPosition: "afterend",
      };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("link[as='image']", dom), 'href')?.trim() ?? '';

      // price
      // get everything between ost pricing and ost recent product pricing
      const regex = /window\._ost\.pricing(.*?)window\._ost\.recentProductPricing/s;
      const match = html.match(regex);

      let price = '';
      if (match) {
          // console.log(match[1]); // This will print the extracted content
           // 'salePrice':10.99000,
          let price_match = match[1].match(/\'salePrice\'\:([\d\.]+)\,/);
          price = price_match?.[1] ?? '';
          if(price == '') {
            // priceTotal: initialize(44.99),
            let price_match2 = match[1].match(/\'retailPrice\'\:([\d\.]+)\,/);
            price = price_match2?.[1] ?? '';
          }
          price = price.replace(",", "");


          price = price.replace("$", "");
          price = price.replace(",", "");
          price = price.replace("USD", "").trim();
      } else {
          console.log("No match found");
      }


     
    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('OreillyAutoParser.js error', err);
      return null;
    }
  }

}

export {OreillyAutoParser};