import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class SmartwoolParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    const urlObj = new URL(url);
    const params = urlObj.searchParams;

    // Create a new URLSearchParams object to store filtered params
    const filteredParams = new URLSearchParams();

    // Iterate through all parameters
    for (const [key, value] of params.entries()) {
        if (key.startsWith('dwvar_')) {
            filteredParams.append(key, value);
        }
    }

    // Construct the new URL with filtered parameters
    urlObj.search = filteredParams.toString();

    return urlObj.toString();
  }
  
  isProductPage(url) {
    // https://www.smartwool.com/en-us/men/apparel/sweaters/mens-heavy-crew-sweater/SW002518.html?dwvar_SW002518_color=M71
    let result = /\/SW00/.test(url);
    return result;
  }

  getMerchant() {
    return 'smartwool';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
      type: 'function',
      fun: function (doc, containing_span) {
        
        doc.querySelectorAll("div[class='b-product_details-top']").forEach((h1, index) => {
          h1.insertAdjacentElement('afterend', containing_span);
        });         

      },
      selector: "div[class='b-product_details-top']",

    };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("title", dom) ?? '')?.trim();
      title = 'Smartwool ' + title;
      title = title.replace(' - Smartwool US', '');
      
      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("img[id='product-image-0.0']", dom), 'src')?.trim() ?? '';

      // price
      let price = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:product:price:amount']", dom), 'content')?.trim() ?? '';
      // if(price == '') {
      //   price =domutils.textContent(CSSselect.selectOne("div[data-dynatrace='product-price']", dom) ?? '')?.trim();
      // }
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
    

      


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('SmartwoolParser.js error', err);
      return null;
    }
  }

}

export {SmartwoolParser};