import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class AceHardwareParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['variationProductCode']);
  }
  
  isProductPage(url) {
    // https://www.acehardware.com/departments/lawn-and-garden/lawn-care/weed-and-vegetation-killers/F012817?variationProductCode=7195332
    // let result = /\/products\//.test(url);
    // return result;

    const regex = /(?:\D*\d){5}/;
    if(url.includes('departments') && regex.test(url)){
      return true;
    }
    else {
      return false;
    }
  }

  getMerchant() {
    return 'acehardware';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
        selector: "h1",
        insertAdjacentPosition: "afterend",
      };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("link[as='image']", dom), 'href')?.trim() ?? '';
      image_link = 'https:'+image_link

      // price
      let price = domutils.textContent(CSSselect.selectOne("div[class='offer-price']", dom) ?? '')?.trim();
      if(price=='') {
        console.log('brian price was empty');
        price = domutils.textContent(CSSselect.selectOne("div[class='price ']", dom) ?? '')?.trim();
      }
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('AceHardwareParser.js error', err);
      return null;
    }
  }

}

export {AceHardwareParser};