import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class BimartParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['variant']);
  }
  
  isProductPage(url) {
    // https://www.glossier.com/products/glossier-you?variant=44056890573045
    let result = /\/p\//.test(url);
    return result;
  }

  getMerchant() {
    return 'bimart';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
        selector: "h1[class='product-title']",
        insertAdjacentPosition: "afterend",
      };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1[class='product-title']", dom) ?? '')?.trim();

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne(".mz-productimages-thumbimage", dom), 'src')?.trim() ?? '';

      // price
      let price_match = html.match(/salePrice\":([\d\.]+)\,\"/);
      let price = price_match?.[1] ?? '';
      if(price == '') {
        // priceTotal: initialize(44.99),
        let price_match2 = html.match(/\"price\"\:([\d\.]+)\,\"/);
        price = price_match2?.[1] ?? '';
      }
      price = price.replace(",", "");
      console.log('price', price);


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('BimartParser.js error', err);
      return null;
    }
  }

}

export {BimartParser};