import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class NetAPorterParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['variant', 'size']);
  }
  
  isProductPage(url) {
    // https://www.net-a-porter.com/en-us/shop/product/adam-lippes/clothing/midi-dresses/edie-belted-cotton-twill-midi-shirt-dress/1647597349677015
    let result = /\/product\//.test(url);
    return result;
  }

  getMerchant() {
    return 'netaporter';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
        selector: "div[class*='ProductInformation']",
        insertAdjacentPosition: "afterend",
      };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("title", dom) ?? '')?.trim();
      title = title.replace(' | NET-A-PORTER', '');

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:image']", dom), 'content')?.trim() ?? '';

      // price
      let price = domutils.textContent(CSSselect.selectOne("span[class*='PriceWithSchema10__value--sale']", dom) ?? '')?.trim();
      if(price == '') {
        price =domutils.textContent(CSSselect.selectOne("span[class='PriceWithSchema10__value']", dom) ?? '')?.trim();
      }
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('NetAPorterParser.js error', err);
      return null;
    }
  }

}

export {NetAPorterParser};