import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class WayfairUkParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['piid']);
  }

  isProductPage(url) {
    // https://www.wayfair.com/kitchen-tabletop/pdp/lark-manor-annibelle-675-kitchen-pantry-w100004087.html?piid=1667708798
    let result = /\/pdp\//.test(url);
    return result;
  }

  getMerchant() {
    return 'wayfairUk';
  }

  merchantIdFromURL(url, html='') {
    // let result = url.match(/product\.([\d]+)\.html/);
    return url;
  }

  getAddAlertInjection() {
    return {
      type: 'function',
      fun: function (doc, containing_span) {
        let titleBlock = doc.querySelector("h1[data-hb-id='Heading']");
        if (titleBlock!=null) {
          titleBlock.insertAdjacentElement('beforebegin', containing_span);
        }
        else {
          let nodes = doc.querySelectorAll("h1[data-hb-id='Heading']");
          nodes.forEach(function(element, index, array) {
            element.insertAdjacentElement('afterend', containing_span);
          });

          // for mobile
          if(nodes.length == 0) {

            titleBlock = doc.querySelector("h1[data-rtl-id='listingHeaderNameHeading']");
            if (titleBlock!=null) {
              titleBlock.insertAdjacentElement('afterend', containing_span);
            }
          }

        }



        // clean up time beacon
        let time_beacon = document.getElementById("pl_extension_time_beacon");
        time_beacon.parentNode.removeChild(time_beacon);
      },
      selector: "#pl_extension_time_beacon",
      
      // insertAdjacentPosition: "afterbegin",
    };
  }

  

  parse(html, url) {
    try {
      const dom = htmlparser2.parseDocument(html);
      // get title, link, merchant_product_id, image_link, price (is shipping diff than pickup?), coupon, details, specifications
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1[data-hb-id='Heading']", dom) ?? '')?.trim();

      // link
      let link = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:url']", dom), 'content')?.trim() ?? '';

      // merchant_product_id - just make link for now
      let merchant_product_id = link;

      // image_link
      let image_link = '';
      let image_link_node = CSSselect.selectOne("div[class='ProductDetailImageCarousel-container'] img", dom);
      if (image_link_node==null) {
        image_link_node = CSSselect.selectOne("div[id='MediaTrayCarouselWithThumbnailSidebar'] img", dom)
      }
      if (image_link_node==null) {
        image_link_node = CSSselect.selectOne("div[data-overly='Features_MediaTray'] img", dom)
      }
      if (image_link_node!=null) { 
        image_link = domutils.getAttributeValue(image_link_node, 'src')?.trim() ?? '';
      }
      if(image_link == '') {
        image_link = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:image']", dom), 'content')?.trim() ?? '';
      }


      // price
      let price = '';
      let price_node = CSSselect.selectOne("div[data-overly='Externals_Pricing'] span[data-test-id='PriceDisplay']", dom);
      if (price_node==null) {
        price_node = CSSselect.selectOne("div[data-overly='Externals_Pricing'] div[data-enzyme-id='PriceBlock'] span", dom);
      }
      if (price_node!=null) {
        price = domutils.textContent(price_node)?.trim();
      }

      // "salePrice":152.99,"
      if(price=='') {
        console.log('price is empty');
        let price_match = html.match(/"salePrice":([\d\.,]+),"/);
        console.log('price_match', price_match);
        price = price_match?.[1] ?? '';
      }

      if(price=='') {
        price = domutils.textContent(CSSselect.selectOne("div[data-name='Pricing'] span[data-test-id='PriceDisplay']", dom) ?? '')?.trim();
      }
      
      price = price.replace("£", "");
      price = price.replace("$", "");
      price = price.replace(",", "");
  
      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    }
    catch (err) {
      console.log('WayfairUkParser.js error', err);
      return null;
    }
  }

}

export {WayfairUkParser};