import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class TimberlandParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['width', 'size']);
  }
  
  isProductPage(url) {
    // https://www.timberland.com/en-us/p/men/clothing/outerwear-0106/mens-water-resistant-utility-insulated-jacket-TB0A6JVNCY2
    let result = /\/p\//.test(url);
    return result;
  }

  getMerchant() {
    return 'timberland';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
        selector: "span[class='subtitle-5']",
        insertAdjacentPosition: "afterend",
      };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("title", dom) ?? '')?.trim();
      title = "Timberland " + title;
      
      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("meta[name='og:image']", dom), 'content')?.trim() ?? '';

      // price
      let price = domutils.textContent(CSSselect.selectOne("ins[class*='dark:c-red-60']", dom) ?? '')?.trim();
      if(price == '') {
        price =domutils.textContent(CSSselect.selectOne("div[data-dynatrace='product-price']", dom) ?? '')?.trim();
      }
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
    

      


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('TimberlandParser.js error', err);
      return null;
    }
  }

}

export {TimberlandParser};