import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"
const he = require('he');

class TargetParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['preselect']);
  }

  isProductPage(url) {
    // https://www.target.com/p/women-s-short-sleeve-v-neck-t-shirt-universal-thread/-/A-93338513?preselect=92878219#lnk=sametab
    let result = /\/p\//.test(url);
    return result;
  }

  getMerchant() {
    return 'target';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  async getRequestInfo() {
    let zip_code_cookie = ParserUtilities.getCookie('GuestLocation');
    let zip_code = zip_code_cookie.split('|')[0];
    
    let store_id = null;
    let preferred_store_url =
      'https://api.target.com/location_fulfillment_aggregations/v1/preferred_stores?'
      + 'key=9f36aeafbe60771e321a7cc95a78140772ab3e96'
      + '&zipcode=' + zip_code;
    console.log('fetching preferred store for zip code', zip_code);

    let preferred_store_url_response = await fetch(preferred_store_url);
    let preferred_store_json = await preferred_store_url_response.json();
    
    if (preferred_store_json?.['preferred_stores']?.length > 0) {
      store_id = preferred_store_json['preferred_stores'][0]['location_id']
      console.log('found store_id', store_id);
    }
    else {
      console.log('could not find store id, length == 0');
    }

    return {
      zip_code:zip_code,
      store_id: store_id
    };

    // https://api.target.com/location_fulfillment_aggregations/v1/preferred_stores?key=9f36aeafbe60771e321a7cc95a78140772ab3e96&zipcode=90035
    
  }


  async fetch(request) {
    
    // {
    //   product_url:...
    //   request_info:...
    // }
    
    console.log('running target fetch');
    
    let tcin_match = request.product_url.match(/\/-\/A-(\d+)/);
    let tcin = tcin_match ? tcin_match[1] : null;

    let url = new URL(request.product_url);
    let params = new URLSearchParams(url.search);
    let preselect_tcin = params.get('preselect');
    console.log('preselect_tcin', preselect_tcin);

    let template_url =
      'https://redsky.target.com/redsky_aggregations/v1/web/pdp_client_v1'
      + '?key=9f36aeafbe60771e321a7cc95a78140772ab3e96'
      + '&tcin=' + tcin
      + '&is_bot=false'
      + '&store_id=' + request.request_info.store_id
      + '&pricing_store_id=' + request.request_info.store_id
      + '&has_pricing_store_id=true&has_financing_options=true&include_obsolete=true'
      // + '&visitor_id=019495329D7102019B9A965591D95F06'
      + '&skip_personalized=true&skip_variation_hierarchy=true&channel=WEB'
      // + '&page=%2Fp%2FA-84783715'
    ;
    console.log('template url', template_url);
    let product_page_response = await fetch(template_url);
    if (product_page_response.ok) {
      let product_json = await product_page_response.json();

      console.log('product_json', product_json);
      
      let price = null;
      let image_link = null;
      let title = null;
      if (product_json?.data?.product?.children) {
        // Find the preselect
        let child = product_json.data.product.children.find( obj => obj.tcin==preselect_tcin );
        console.log('child: ', child);
        if (child!=null) {
          title = he.decode(child?.item?.product_description?.title);
          price = child?.price?.current_retail;
          image_link = child?.item?.enrichment?.image_info?.primary_image?.url;
          
        }
      }
      else if (product_json?.data?.product) {
        title = he.decode(product_json?.data?.product?.item?.product_description?.title);
        price = product_json?.data?.product?.price?.current_retail;
        image_link = product_json?.data?.product?.item?.enrichment?.image_info?.primary_image?.url;
      }

      let product = {
        'title': title,
        'link': this.normalizeUrl(request.product_url),
        'merchant_product_id': this.normalizeUrl(request.product_url),
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    }
  }

  getAddAlertInjection() {
    return {
      selector: "div[data-module-type='ProductDetailTitle']",
      insertAdjacentPosition: "afterbegin",
    };
  }

  parse(html, url) {
    try {
      const dom = htmlparser2.parseDocument(html);
      // get title, link, merchant_product_id, image_link, price (is shipping diff than pickup?), coupon, details, specifications
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();

      // link
      let link = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:url']", dom), 'content')?.trim() ?? '';

      // merchant_product_id - just make link for now
      let merchant_product_id = link.split("/").pop();

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:image']", dom), 'content')?.trim() ?? '';

      // price
      let price = domutils.textContent(CSSselect.selectOne("span[itemprop='price']", dom) ?? '')?.trim();
      price = price.replace("Now ", "");
      price = price.replace("$", "");
      price = price.replace(",", "");
      
  
      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    }
    catch (err) {
      console.log('TargetParser.js error', err);
      return null;
    }
  }

}

export {TargetParser};