import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class UnderArmourParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    const urlObj = new URL(url);
    const params = urlObj.searchParams;

    // Create a new URLSearchParams object to store filtered params
    const filteredParams = new URLSearchParams();

    // Iterate through all parameters
    for (const [key, value] of params.entries()) {
        if (key.startsWith('dwvar_') || key=='pid') {
            filteredParams.append(key, value);
        }
    }

    // Construct the new URL with filtered parameters
    urlObj.search = filteredParams.toString();

    return urlObj.toString();
  }
  
  isProductPage(url) {
    // https://www.newbalance.com/pd/athletics-tank/WT41250.html?dwvar_WT41250_style=WT41250NNH#dwvar_WT41250_style=WT41250BKH&pid=WT41250&quantity=1
    let result = /\/p/.test(url);
    return result;
  }

  getMerchant() {
    return 'underarmour';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }


  getAddAlertInjection() {
    return {
      type: 'function',
      fun: function (doc, containing_span) {
        doc.querySelectorAll("h1").forEach((h1, index) => {
          h1.insertAdjacentElement('afterend', containing_span);
        });         
        
      },
      selector: "h1",

    };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();
      title = 'Under Armour ' + title;
      
      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link_match = html.match(/\"image\"\: \[[\s]+\"(.*)\"\,/);
      let image_link = image_link_match?.[1] ?? '';
      if(image_link == '') {
        image_link = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:image']", dom), 'content')?.trim() ?? '';
      }


      // price
      let price = domutils.textContent(CSSselect.selectOne("span[data-testid='price-display-sales-price']", dom) ?? '')?.trim();
      if(price == '') {
        price =domutils.textContent(CSSselect.selectOne("span[data-testid='price-display-list-price']", dom) ?? '')?.trim();
      }
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
    

      


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('UnderArmourParser.js error', err);
      return null;
    }
  }

}

export {UnderArmourParser};