import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class LandsEndParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['attributes']);
  }
  
  isProductPage(url) {
    // https://bombas.com/products/women-s-solid-ankle-sock-white-medium?variant=white&size=m
    let result = /\/products\//.test(url);
    return result;
  }

  getMerchant() {
    return 'landsend';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
      type: 'function',
      fun: function (doc, containing_span) {
        let price = document.querySelector('.product-price')?.textContent;
        price = price.split("\n")[0];
        console.log('injection price', price);
        // if contains price range return null, so won't inject
        if(price.includes('-')) {
          console.log('contains -');
          let titleBlock = doc.querySelector("title");
          titleBlock.insertAdjacentElement('afterend', containing_span);
          return null;
        }
       
          let titleBlock = doc.querySelector("h1");
          titleBlock.insertAdjacentElement('afterend', containing_span);

        return;
      },
      selector: "h1",
    };
  }


  // getAddAlertInjection() {
  //   return {
  //       selector: "h1",
  //       insertAdjacentPosition: "afterend",
  //     };
  // }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();
      title = "Lands' End " + title;

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:image']", dom), 'content')?.trim() ?? '';
      image_link = 'https://'+image_link;

      

      // price
      let price = domutils.getAttributeValue(CSSselect.selectOne("meta[itemprop='price']", dom), 'content')?.trim() ?? '';
      
      if(price == '') {
        price = domutils.textContent(CSSselect.selectOne(".product-price", dom) ?? '')?.trim();
        price = price.split("\n")[0];
        // if contains price range return null, so won't inject
        if(price.includes('-')) {
          console.log('price looks like:', price);
          console.log('parser price contained -');
          return null;
        }
      }
      
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('LandsEndParser.js error', err);
      return null;
    }
  }

}

export {LandsEndParser};