import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class FashionNovaParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, []);
  }
  
  isProductPage(url) {
    // https://www.fashionnova.com/products/dont-sugarcoat-it-slides-white
    let result = /\/products\//.test(url);
    return result;
  }

  getMerchant() {
    return 'fashionnova';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }


  getAddAlertInjection() {
    return {
      type: 'function',
      fun: function (doc, containing_span) {
        
        doc.querySelectorAll("h1[data-testid='product-title']").forEach((h1, index) => {
          h1.insertAdjacentElement('afterend', containing_span);
        });         

      },
      selector: "h1[data-testid='product-title']",

    };
  }
  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:title']", dom), 'content')?.trim() ?? '';
      title = title.replace('', '');

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("link[as='image']", dom), 'href')?.trim() ?? '';

      // price
      let price_match = html.match(/"price"\:"([^"]+)/);
      let price = price_match?.[1] ?? '';
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('FashionNovaParser.js error', err);
      return null;
    }
  }

}

export {FashionNovaParser};