import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class SephoraParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['skuId']);
  }
  
  isProductPage(url) {
    // https://www.sephora.com/product/summer-fridays-lip-butter-balm-P455936?skuId=2495497
    let result = /\/product\//.test(url);
    return result;
  }

  getMerchant() {
    return 'sephora';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
      type: 'function',
      fun: function (doc, containing_span) {
        
        doc.querySelectorAll("h1").forEach((h1, index) => {
          h1.insertAdjacentElement('beforebegin', containing_span);
        });         

      },
      selector: "h1",

    };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("title", dom) ?? '')?.trim();
      title = title.replace(' | Sephora', '');
      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("link[as='image']", dom), 'href')?.trim() ?? '';

      // price
      let price = domutils.textContent(CSSselect.selectOne("p[data-comp='Price '] b:first-of-type", dom) ?? '')?.trim();
      if(price == '') {
        price = domutils.textContent(CSSselect.selectOne("b[class='css-0']", dom) ?? '')?.trim();
      }
      if(price == '') {
        price = domutils.textContent(CSSselect.selectOne("b[class*='css-']", dom) ?? '')?.trim();
      }
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('SephoraParser.js error', err);
      return null;
    }
  }

}

export {SephoraParser};