import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class SamsungParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['variant', 'size']);
  }
  
  isProductPage(url) {
    // https://www.samsung.com/us/home-appliances/dryers/electric/bespoke-7-6-cu-ft-ultra-capacity-electric-dryer-with-super-speed-dry-and-ai-smart-dial-in-brushed-black-dve53bb8700va3/
    let result = /\-[a-z][a-z]?[a-z]?[\d][\d]/.test(url);
    return result;
  }

  getMerchant() {
    return 'samsung';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
        selector: "h1",
        insertAdjacentPosition: "afterend",
      };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();
      title = "Samsung " + title;

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = '';
      let image_link_node = CSSselect.selectOne("link[as='image']", dom) ?? '';
      if(image_link_node == '' ) {
        image_link = domutils.getAttributeValue(image_link_node, 'href')?.trim() ?? '';
        if(image_link == '' ) {
          console.log('image link not found');
          let image_link_match = html.match(/"galleryLifestyleImages":\s*\[\s*"([^"]+)"/);
          image_link = image_link_match?.[1] ?? '';
        }
        if(image_link == '' ) {
          console.log('image link not found2');
          let image_link_node2 = CSSselect.selectOne("picture", dom) ?? '';
          image_link = domutils.getAttributeValue(image_link_node2, 'data-small')?.trim() ?? '';
        }
      }
      else {
        image_link = domutils.getAttributeValue(image_link_node, 'href')?.trim() ?? '';
      }

      // price
      
      let price = domutils.textContent(CSSselect.selectOne("span[class*='font-price']", dom) ?? '')?.trim();
      if(price == '') {
        price = domutils.textContent(CSSselect.selectOne("span[class*='Price']", dom) ?? '')?.trim();
        if(price == '') {
          price = domutils.textContent(CSSselect.selectOne("span[class*='__price']", dom) ?? '')?.trim();
          if(price == '') {
            let price_match = html.match(/\,\"price\"\:\"([\d\.]+)\"\,/);
            price = price_match?.[1] ?? '';
            console.log('tried regex');
            if(price == '') {
              let price_match2 = html.match(/\"priceDisplay\"\:\"\$([\d\.\,]+)\"\,\"/);
              price = price_match2?.[1] ?? '';
              console.log('tried regex2');
            }
          }
        }
      }
      if(price.includes('{{price')) {
        let price_match2 = html.match(/"priceDisplay\"\:\"\$([\d\.\,]+)\"\,/);
        price = price_match2?.[1] ?? '';
      }

      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('SamsungParser.js error', err);
      return null;
    }
  }

}

export {SamsungParser};