import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class CvsParser {
  watchURLChanges() {
    return false;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['skuId']);
  }

  isProductPage(url) {
    // https://www.cvs.com/shop/revlon-nail-enamel-prodid-1013875?skuId=320278
    let result = /prodid\-[\d]+/.test(url);
    return result;
  }

  getMerchant() {
    return 'cvs';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
      selector: "h1",
      insertAdjacentPosition: "afterbegin",
    };
  }

  

  parse(html, url) {
    try {
      const dom = htmlparser2.parseDocument(html);
      // get title, link, merchant_product_id, image_link, price (is shipping diff than pickup?), coupon, details, specifications
      
      // title
			let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();

			// link - remove all URL parameters
			let link = domutils.getAttributeValue(CSSselect.selectOne("link[rel='canonical']", dom), 'href')?.trim() ?? '';
			if(link.includes('&')) {
					link = link.substring(0, link.indexOf("&"));
			}

			// merchant_product_id - just make link
			let merchant_product_id = link;

			// image_link
			let image_link = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:image']", dom), 'content')?.trim() ?? '';
      image_link = image_link.replace('http://localhost:4300', 'https://www.cvs.com', );

			// price
			//a[class~="logo"] 
			let price_match = html.match(/"price":"([\d\.]+)"\,"/);
      let price = price_match?.[1] ?? '';
			price = price.replace("Price ", "");
			price = price.replace(/\.$/, "");
			price = price.replace(",", "");
  
      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    }
    catch (err) {
      console.log('CvsParser.js error', err);
      return null;
    }
  }

}

export {CvsParser};