import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class BedBathAndBeyondParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['option']);
  }
  
  isProductPage(url) {
    // https://www.bedbathandbeyond.com/Bedding-Bath/Modern-Threads-Braelyn-4-Piece-Garment-Washed-Comforter-Set/30886572/product.html?refccid=W6ZYFSWFE3CI52KAMQRVO4S4FI&searchidx=0&option=55770307
    let result = /product\.html/.test(url);
    return result;
  }

  getMerchant() {
    return 'bedbathandbeyond';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
      type: 'function',
      fun: function (doc, containing_span) {
        let price = document.querySelector("div[data-testid='current-price']")?.textContent;
        // price = price.split("\n")[0];
        console.log('injection price', price);
        // if contains price range return null, so won't inject
        if(price.includes('From')) {
          console.log('contains From');
          let titleBlock = doc.querySelector("title");
          titleBlock.insertAdjacentElement('afterend', containing_span);
          return null;
        }
       
          let titleBlock = doc.querySelector("h1");
          titleBlock.insertAdjacentElement('afterend', containing_span);

        return;
      },
      selector: "h1",
    };
  }

  // getAddAlertInjection() {
  //   return {
  //       selector: "h1",
  //       type: 'function',
  //       fun: function (doc, containing_span) {
          
  //         doc.querySelectorAll("h1").forEach((h1, index) => {
  //           h1.insertAdjacentElement('beforebegin', containing_span);
  //         });         
  //       },

  //     };
  // }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("link[rel='preload']", dom), 'href')?.trim() ?? '';
      if(image_link.includes('.css')) {
        image_link = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:image']", dom), 'content')?.trim() ?? '';
      }

      // price
      let price = domutils.textContent(CSSselect.selectOne("div[data-testid='current-price'] span[data-price='domestic']", dom) ?? '')?.trim();
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('BedBathAndBeyondParser.js error', err);
      return null;
    }
  }

}

export {BedBathAndBeyondParser};