import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class SteveMaddenParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, []);
  }
  
  isProductPage(url) {
    // https://www.glossier.com/products/glossier-you?variant=44056890573045
    let result = /\/products\//.test(url);
    return result;
  }

  getMerchant() {
    return 'stevemadden';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
        selector: "div[class='product__title desktop_product_title']",
        insertAdjacentPosition: "afterend",
      };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:title']", dom), 'content')?.trim() ?? '';

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:image']", dom), 'content')?.trim() ?? '';

      // price
      let price = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:price:amount']", dom), 'content')?.trim() ?? '';
      // check if there is a promo available

      let promo_price = '';
      let promo_price_node = CSSselect.selectOne("div[class='fs-custom-single-promo fs-promo-text cs-promo-text-custom promo-text']", dom);
      if (promo_price_node!=null) {
        promo_price =  domutils.getAttributeValue(promo_price_node, 'data-promo-price')?.trim() ?? '';
      }

      if(promo_price !== '') {
        price = promo_price;   
      }
      
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('SteveMaddenParser.js error', err);
      return null;
    }
  }

}

export {SteveMaddenParser};