import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class HomeDepotParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, []);
  }
  
  isProductPage(url) {
    // https://www.homedepot.com/p/Amazon-Fire-TV-Stick-4K-streaming-device-includes-support-for-Wi-Fi-6-Dolby-Vision-Atmos-free-live-TV-B0CJM1GNFQ/331714985
    let result = /\/p\//.test(url);
    return result;
  }

  getMerchant() {
    return 'homedepot';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
      type: 'function',
      fun: function (doc, containing_span) {
        let titleBlock = doc.querySelector("h1");
        titleBlock.insertAdjacentElement('beforebegin', containing_span);
        return;
      },
      selector: "h1",
    };
  }


  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("link[id='thd-helmet__link--preloadImg']", dom), 'href')?.trim() ?? '';

      // price
      let price_match = html.match(/\,\"price\"\:([\d\.\,]+)\,\"/);
      let price = price_match?.[1] ?? '';

      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('HomeDepotParser.js error', err);
      return null;
    }
  }

}

export {HomeDepotParser};