import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class HonestParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, []);
  }
  
  isProductPage(url) {
    // https://www.honest.com/clean-conscious-diaper-pattern-play-size-2/H1155DPRPPS2S.html
    let result = /\/([A-Z][\w]+)\.html/.test(url);
    return result;
  }

  getMerchant() {
    return 'honest';
  }

  merchantIdFromURL(url, html='') {
    let result = url.match( /\/([A-Z][\w]+)\.html/);
    return result?.[1];
  }

  getAddAlertInjection() {
    return {
      selector: "h1[class='product-name d-none d-lg-block']",
      insertAdjacentPosition: "afterend",
    };
  }

  

  parse(html, url) {
    try {
      const dom = htmlparser2.parseDocument(html);
      // get title, link, merchant_product_id, image_link, price (is shipping diff than pickup?), coupon, details, specifications
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();

      // link
      let link = domutils.getAttributeValue(CSSselect.selectOne("link[rel='canonical']", dom), 'href')?.trim() ?? '';

      // merchant_product_id
      let merchant_product_id = domutils.getAttributeValue(CSSselect.selectOne("body", dom), 'data-querystring')?.trim() ?? '';
      merchant_product_id = merchant_product_id.replace("pid=", "");

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("img[fetchpriority='high']", dom), 'src')?.trim() ?? '';

      // price
      let price = domutils.textContent(CSSselect.selectOne("span[class='price-wrapper'] span[class='value ']", dom) ?? '')?.trim();
      price = price.replace("$", "");
      price = price.replace(",", "");

      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      console.log(product);
      return product;
    }
    catch (err) {
      console.log('HonestParser.js error', err);
      return null;
    }
  }

}

export {HonestParser};