import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class BoseParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    const urlObj = new URL(url);
    const params = urlObj.searchParams;

    // Create a new URLSearchParams object to store filtered params
    const filteredParams = new URLSearchParams();

    // Iterate through all parameters
    for (const [key, value] of params.entries()) {
        if (key.startsWith('dwvar_') || key=='region') {
            filteredParams.append(key, value);
        }
    }

    // Construct the new URL with filtered parameters
    urlObj.search = filteredParams.toString();

    return urlObj.toString();
  }
  
  isProductPage(url) {
    // https://www.bose.com/p/headphones/bose-quietcomfort-ultra-headphones/QCUH-HEADPHONEARN.html?dwvar_QCUH-HEADPHONEARN_color=DEEP%20PLUM&quantity=1
    let result = /\/p\//.test(url);
    return result;
  }

  getMerchant() {
    return 'bose';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
        selector: "h1",
        insertAdjacentPosition: "afterend",
      };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("img[page='pdp']", dom), 'src')?.trim() ?? '';

      // price
      let price_match = html.match(/\"price\"\: \"([\d\.\,]+)\"\,/);
      let price = price_match?.[1] ?? '';
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('BoseParser.js error', err);
      return null;
    }
  }

}

export {BoseParser};