import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class WalmartParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, []);
  }

  isProductPage(url) {
    // https://www.walmart.com/ip/Allewie-Queen-Size-Metal-Platform-Bed-Frame-with-Square-Frame-Wooden-Headboard-Footboard-Brown/303521634
    let result = /\/ip\//.test(url);
    return result;
  }

  getMerchant() {
    return 'walmart';
  }

  merchantIdFromURL(url, html='') {
    let result = url.match(/\/ip\/([\w]|\-)+\/([\d]+)/);
    return result?.[2];
  }

  getAddAlertInjection() {
    let operating_system = ParserUtilities.getOperatingSystem()
    let device = 'desktop';
    
    let is_mobile = 
      operating_system == 'iPad'
      || operating_system == 'iPhone';
    
    console.log('in getAddAlertInjection, mobile?', is_mobile);
    if (is_mobile) {
      return {
        selector: "h1",
        insertAdjacentPosition: "afterbegin",
      };
    }
    else {
      return {
        selector: "div[class*='buy-box-container']",
        insertAdjacentPosition: "afterbegin",
      };
    }

  }

  

  parse(html, url) {
    try {
      let operating_system = ParserUtilities.getOperatingSystem()
      let device = 'desktop';
      
      let is_mobile = 
        operating_system == 'iPad'
        || operating_system == 'iPhone';
      
      const dom = htmlparser2.parseDocument(html);
      // get title, link, merchant_product_id, image_link, price (is shipping diff than pickup?), coupon, details, specifications
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();

      // link
      let link = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:url']", dom), 'content')?.trim() ?? '';

      // merchant_product_id - just make link for now
      let merchant_product_id = link.split("/").pop();

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:image']", dom), 'content')?.trim() ?? '';

      // price
      let price = null;
      if (is_mobile) {
        let product_info_text = domutils.textContent(CSSselect.selectOne("script[data-seo-id='schema-org-product']", dom) ?? '')?.trim();
        // console.log(product_info_text);
        let product_info = JSON.parse(product_info_text);
        price = product_info?.offers?.[0]?.price ?? null;
      }
      else {
        price = domutils.textContent(CSSselect.selectOne("span[itemprop='price']", dom) ?? '')?.trim();
        price = price.replace("Now ", "");
        price = price.replace("$", "");
        price = price.replace(",", "");
      }
      
  
      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    }
    catch (err) {
      console.log('WalmartParser.js error', err);
      return null;
    }
  }

}

export {WalmartParser};