import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class JanieAndJackParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['variant', 'size']);
  }
  
  isProductPage(url) {
    // https://www.janieandjack.com/item/girls-the-flower-show-dress-102821001.html?lang=en_US
    let result = /\/item\//.test(url);
    return result;
  }

  getMerchant() {
    return 'janieandjack';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
        selector: "div[class='prices']",
        type: 'function',
        fun: function (doc, containing_span) {
          
          doc.querySelectorAll("div[class='prices']").forEach((h1, index) => {
            h1.insertAdjacentElement('beforebegin', containing_span);
          });         
        },

      };
  }

  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();
      title = "Janie and Jack " + title;

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("div[class='carousel-item desktop-zoom active'] img", dom), 'src')?.trim() ?? '';

      // price
      let price = domutils.textContent(CSSselect.selectOne("span[class*='sales']", dom) ?? '')?.trim();
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
    


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('JanieAndJackParser.js error', err);
      return null;
    }
  }

}

export {JanieAndJackParser};