import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class MacysParser {
  watchURLChanges() {
    return false;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, ['ID', 'CategoryID']);
  }

  isProductPage(url) {
    // https://www.macys.com/shop/product/tommy-hilfiger-mens-modern-fit-linen-sport-coat?ID=20066548&CategoryID=16499
    let result = /\/shop\/product\//.test(url);
    return result;
  }

  getMerchant() {
    return 'macys';
  }

  merchantIdFromURL(url, html='') {
    let result = url.match(/\?ID=([\d]+)/);
    return result?.[1];
  }

  getAddAlertInjection() {
    return {
      selector: "div[class='price-wrapper'],div[class='promo price-wrapper']",
      insertAdjacentPosition: "beforebegin",
    };
  }

  

  parse(html, url) {
    try {
      const dom = htmlparser2.parseDocument(html);
      // get title, link, merchant_product_id, image_link, price (is shipping diff than pickup?), coupon, details, specifications
      
      // title
      let title = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:title']", dom), 'content')?.trim() ?? '';
      title = title.replace(" - Macy's", '');  

      // link
      let link = 'https://www.macys.com'+domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:url']", dom), 'content')?.trim() ?? '';
      link = link.replace('&cm_mmc=Facebook-_-pdpshare-_-n-_-n', '');

      // merchant_product_id
      let merchant_product_id = '';
      let merchant_product_id_match = link.match(/\?ID=([\d]+)/);
      merchant_product_id = merchant_product_id_match[1];

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:image']", dom), 'content')?.trim() ?? '';

      // price
      let price_match = html.match(/\"price\"\:\"([\d\.\,]+)\"\,\"/);
      let price = price_match?.[1] ?? '';


      price = price.replace("$", "");
      price = price.replace(",", "");
  
      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    }
    catch (err) {
      console.log('MacysParser.js error', err);
      return null;
    }
  }

}

export {MacysParser};