import * as htmlparser2 from "htmlparser2";
import * as domutils from "domutils"
const render = require("dom-serializer").default;
const CSSselect = require("css-select");
import * as ParserUtilities from "./ParserUtilities.js"

class HomeDepotCaParser {
  watchURLChanges() {
    return true;
  }
  
  normalizeUrl(url) {
    return ParserUtilities.filterUrlParameters(url, []);
  }
  
  isProductPage(url) {
    // https://www.homedepot.ca/product/lg-electronics-24-inch-w-top-control-dishwasher-with-quadwash-3rd-rack-and-dynamic-dry-in-stainless-steel-48-dba-energy-star-/1001863571
    let result = /\/product\//.test(url);
    return result;
  }

  getMerchant() {
    return 'homedepotCa';
  }

  merchantIdFromURL(url, html='') {
    return this.normalizeUrl(url);
  }

  getAddAlertInjection() {
    return {
      type: 'function',
      fun: function (doc, containing_span) {
        let titleBlock = doc.querySelector("h1");
        titleBlock.insertAdjacentElement('beforebegin', containing_span);
        return;
      },
      selector: "h1",
    };
  }


  

  parse(html, url) {
    try {
    
      const dom = htmlparser2.parseDocument(html);
      
      // title
      let title = domutils.textContent(CSSselect.selectOne("h1", dom) ?? '')?.trim();

      // link
      let link = this.normalizeUrl(url);

      // merchant_product_id
      let merchant_product_id = link;

      // image_link
      let image_link = domutils.getAttributeValue(CSSselect.selectOne("meta[property='og:image']", dom), 'content')?.trim() ?? '';

      let price = domutils.textContent(CSSselect.selectOne("span[itemprop='price']", dom) ?? '')?.trim();
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
      // console.log('price', price);
      
      /*
      // price
      let price = domutils.textContent(CSSselect.selectOne("div[data-testid='current-price'] span[data-price='domestic']", dom) ?? '')?.trim();
      price = price.replace("$", "");
      price = price.replace(",", "");
      price = price.replace("USD", "").trim();
      */


      let product = {
        'title': title,
        'link': link,
        'merchant_product_id': merchant_product_id,
        'image_link': image_link,
        'price': price,
        'coupon_raw_text': null,
        'coupon_type': null,
        'coupon_amount': null,
      };
      return product;
    
    }
    catch (err) {
      console.log('HomeDepotCaParser.js error', err);
      return null;
    }
  }

}

export {HomeDepotCaParser};